insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f5000000-0000-0000-0000-000000000001', 'mrcp1', '66dbeeb3-f3ab-4d0c-98f6-e5d8e53224f6',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f5000000-0000-0000-0000-000000000001', 'A', 'Simple reassurance and discharge with no further action', false, 'Ruled out because recurrent falls in an older adult warrant proper assessment to identify and address modifiable risk factors, not simple reassurance without further evaluation.', 1),
('f5000000-0000-0000-0000-000000000001', 'B', 'Immediate long-term care placement', false, 'Ruled out because this is a disproportionate response without first conducting a proper falls assessment; many contributing factors are modifiable, and appropriate intervention may allow her to remain safely at home.', 2),
('f5000000-0000-0000-0000-000000000001', 'C', 'Referral for hip replacement surgery', false, 'Ruled out because there is no indication of hip pathology or injury described; this is not an appropriate response to recurrent falls without evidence of a specific joint problem.', 3),
('f5000000-0000-0000-0000-000000000001', 'D', 'Prescription of a sedative to help her sleep and reduce nighttime falls', false, 'Ruled out because sedatives increase falls risk in older adults (through sedation, impaired balance and cognition) and would be counterproductive, rather than an appropriate falls prevention measure.', 4),
('f5000000-0000-0000-0000-000000000001', 'E', 'Comprehensive multifactorial falls risk assessment', true, 'Correct. A patient with recurrent falls (two or more in the past year, or presenting following a fall) should undergo a comprehensive multifactorial falls risk assessment, addressing gait/balance, vision, cognition, cardiovascular causes (e.g. postural hypotension, arrhythmia), medication review, home hazards and bone health, given the multiple potential contributing factors in older adults.', 5),
('f5000000-0000-0000-0000-000000000002', 'A', 'Vasovagal syncope', false, 'Ruled out because vasovagal syncope typically has a different triggering pattern (e.g. prolonged standing, pain, emotional stress) and is not specifically defined by this standardised lying-to-standing blood pressure drop criterion.', 1),
('f5000000-0000-0000-0000-000000000002', 'B', 'Postural (orthostatic) hypotension', true, 'Correct. A drop in systolic blood pressure of at least 20 mmHg or diastolic of at least 10 mmHg within 3 minutes of standing, with reproduction of symptoms, confirms postural hypotension, an important and modifiable contributor to falls risk in older adults, warranting review of contributing medications and other causes.', 2),
('f5000000-0000-0000-0000-000000000002', 'C', 'Cardiac arrhythmia', false, 'Ruled out because although arrhythmia is an important differential for dizziness/falls, the specific, reproducible blood pressure drop on standing meeting defined criteria confirms postural hypotension as the cause here.', 3),
('f5000000-0000-0000-0000-000000000002', 'D', 'Vestibular dysfunction', false, 'Ruled out because vestibular causes of dizziness are typically triggered by head movement rather than specifically by postural change with a confirmed matching blood pressure drop.', 4),
('f5000000-0000-0000-0000-000000000002', 'E', 'Normal physiological response to standing', false, 'Ruled out because the magnitude of blood pressure drop described (25/12 mmHg) exceeds the normal physiological range and meets defined diagnostic criteria for postural hypotension, particularly given that it reproduces his symptoms.', 5),
('f5000000-0000-0000-0000-000000000003', 'A', 'Normal, healthy ageing requiring no specific attention', false, 'Ruled out because this specific constellation of findings represents a recognised clinical syndrome (frailty) associated with increased risk of adverse outcomes, not simply normal, healthy ageing without clinical significance.', 1),
('f5000000-0000-0000-0000-000000000003', 'B', 'Major depressive disorder alone', false, 'Ruled out because although some symptoms could overlap with depression (e.g. exhaustion), the specific combination described (weight loss, weakness, slow gait, low activity) reflects the recognised physical frailty phenotype rather than a primary mood disorder diagnosis alone, though depression should still be considered/screened for as a contributing or coexisting factor.', 2),
('f5000000-0000-0000-0000-000000000003', 'C', 'Frailty syndrome (physical frailty phenotype)', true, 'Correct. The combination of unintentional weight loss, exhaustion, weakness (reduced grip strength), slow gait speed and low physical activity represents the recognised physical frailty phenotype (Fried criteria); meeting three or more of these five criteria defines frailty, a distinct clinical syndrome associated with increased vulnerability to adverse health outcomes.', 3),
('f5000000-0000-0000-0000-000000000003', 'D', 'Simple deconditioning from inactivity alone, with no broader significance', false, 'Ruled out because although reduced activity is one component, the frailty phenotype represents a broader, clinically significant syndrome with recognised prognostic implications, not simply isolated deconditioning.', 4),
('f5000000-0000-0000-0000-000000000003', 'E', 'Cachexia specifically related to underlying malignancy', false, 'Ruled out because although weight loss can occur with malignancy, the specific combination described represents the broader frailty phenotype criteria, and malignancy would need to be specifically investigated for as a potential underlying cause rather than assumed.', 5),
('f5000000-0000-0000-0000-000000000004', 'A', 'Parkinsonian gait disturbance, including freezing of gait and postural instability', true, 'Correct. Festinating gait (short, shuffling, accelerating steps), reduced arm swing, and freezing episodes (sudden, brief inability to initiate or continue movement, particularly when turning or navigating obstacles like doorways) are characteristic Parkinsonian gait features that significantly increase falls risk, alongside postural instability from impaired righting reflexes.', 1),
('f5000000-0000-0000-0000-000000000004', 'B', $x$Simple age-related deconditioning unrelated to his Parkinson's disease$x$, false, 'Ruled out because these are specific, well-recognised Parkinsonian gait features directly related to his underlying neurodegenerative disease, not simply generic deconditioning.', 2),
('f5000000-0000-0000-0000-000000000004', 'C', 'Peripheral neuropathy as the primary cause', false, 'Ruled out because the specific gait pattern described (festination, freezing, particularly triggered by turning/doorways) is characteristic of Parkinsonian gait disturbance, not the sensory ataxic or foot-drop pattern typical of peripheral neuropathy.', 3),
('f5000000-0000-0000-0000-000000000004', 'D', 'Cerebellar ataxia', false, 'Ruled out because cerebellar ataxia causes a wide-based, unsteady gait with dysmetria, distinct from the specific festinating, freezing pattern described here, which is characteristic of Parkinsonism.', 4),
('f5000000-0000-0000-0000-000000000004', 'E', 'Simple visual impairment as the primary cause', false, 'Ruled out because although visual impairment can contribute to falls generally, the specific gait pattern described (festination, freezing triggered by turning and doorways) is characteristic of Parkinsonian gait disturbance specifically.', 5),
('f5000000-0000-0000-0000-000000000005', 'A', 'A single specialist medical consultation focused only on the primary presenting complaint', false, 'Ruled out because comprehensive geriatric assessment is specifically broader than a single-issue medical consultation, deliberately encompassing multiple domains beyond just the presenting complaint.', 1),
('f5000000-0000-0000-0000-000000000005', 'B', 'A purely physical examination without any input from other disciplines', false, 'Ruled out because comprehensive geriatric assessment is inherently multidisciplinary, typically involving input from various professionals (medical, nursing, physiotherapy, occupational therapy, social work, pharmacy) rather than relying on physical examination alone.', 2),
('f5000000-0000-0000-0000-000000000005', 'C', 'An assessment focused exclusively on determining a diagnosis, without consideration of functional or social factors', false, 'Ruled out because a defining feature of comprehensive geriatric assessment is its holistic scope, explicitly including functional and social domains alongside medical diagnosis, not diagnosis in isolation.', 3),
('f5000000-0000-0000-0000-000000000005', 'D', 'A multidimensional, multidisciplinary assessment addressing medical, functional, psychological and social domains, leading to a coordinated care plan', true, $x$Correct. Comprehensive geriatric assessment is a multidimensional, interdisciplinary diagnostic process that evaluates an older person's medical, functional, psychological (cognitive and mood) and social/environmental circumstances, leading to a coordinated, individualised management plan, and has been shown to improve outcomes for frail older adults.$x$, 4),
('f5000000-0000-0000-0000-000000000005', 'E', 'A one-off assessment with no ongoing care planning', false, 'Ruled out because comprehensive geriatric assessment specifically culminates in a coordinated, ongoing care plan, not simply a standalone assessment without follow-through.', 5),
('f5000000-0000-0000-0000-000000000006', 'A', 'Simple dehydration requiring only oral fluids', false, 'Ruled out because although dehydration is a relevant contributing factor after a long lie, the markedly raised creatine kinase specifically indicates rhabdomyolysis, which requires more aggressive IV fluid management and monitoring than oral rehydration alone.', 1),
('f5000000-0000-0000-0000-000000000006', 'B', $x$Rhabdomyolysis and acute kidney injury from a prolonged 'long lie'$x$, true, $x$Correct. A prolonged period on the floor after a fall ('long lie') can cause pressure-related muscle breakdown (rhabdomyolysis), reflected by the raised creatine kinase, with resulting myoglobin release risking acute kidney injury; this requires prompt aggressive IV fluid resuscitation and monitoring of renal function and electrolytes (particularly potassium).$x$, 2),
('f5000000-0000-0000-0000-000000000006', 'C', 'Urinary tract infection as the primary concern', false, 'Ruled out because there is no specific evidence of infection described, and the markedly raised creatine kinase and history of a prolonged long lie point specifically to rhabdomyolysis as the priority concern requiring urgent management.', 3),
('f5000000-0000-0000-0000-000000000006', 'D', 'Simple confusion from anxiety about the fall, requiring reassurance only', false, 'Ruled out because the confusion in this context, combined with the biochemical findings, more likely reflects a metabolic complication (e.g. from AKI/electrolyte disturbance) of the prolonged long lie, requiring active medical assessment and treatment, not simple reassurance.', 4),
('f5000000-0000-0000-0000-000000000006', 'E', 'No specific medical intervention needed beyond assistance to stand up', false, 'Ruled out because the biochemical findings (raised creatine kinase, raised urea) indicate significant medical complications from the prolonged long lie requiring active treatment, not simply physical assistance to stand.', 5),
('f5000000-0000-0000-0000-000000000007', 'A', 'Cognitive function specifically', false, 'Ruled out because although cognition can influence performance, the Timed Up and Go test primarily assesses physical functional mobility (gait, balance, transfers), not cognitive function directly; other specific tools are used for cognitive assessment.', 1),
('f5000000-0000-0000-0000-000000000007', 'B', 'Cardiovascular fitness specifically', false, 'Ruled out because this test is not designed as a cardiovascular fitness assessment; it specifically evaluates functional mobility and balance relevant to falls risk.', 2),
('f5000000-0000-0000-0000-000000000007', 'C', 'Bone mineral density', false, 'Ruled out because bone mineral density is assessed by DEXA scanning, not by a functional mobility test such as Timed Up and Go.', 3),
('f5000000-0000-0000-0000-000000000007', 'D', 'Functional mobility, including gait speed, balance and transfer ability', true, 'Correct. The Timed Up and Go test measures the time taken to rise from a chair, walk a short distance, turn, walk back and sit down again, providing a quick, practical assessment of functional mobility, balance and transfer ability, with a prolonged time indicating increased falls risk.', 4),
('f5000000-0000-0000-0000-000000000007', 'E', 'Visual acuity', false, 'Ruled out because visual acuity is assessed separately (e.g. via formal vision testing); the Timed Up and Go test evaluates functional mobility, not vision specifically, though visual impairment could indirectly affect performance.', 5),
('f5000000-0000-0000-0000-000000000008', 'A', 'Falls risk and osteoporosis are entirely unrelated conditions with no interaction', false, 'Ruled out because falls and bone fragility interact directly to determine fracture risk; a fall in a patient with osteoporotic bone is far more likely to result in a fracture than the same fall in a patient with normal bone density.', 1),
('f5000000-0000-0000-0000-000000000008', 'B', 'Addressing osteoporosis alone is sufficient, and falls risk assessment adds no additional value', false, 'Ruled out because even with optimal bone-protective treatment, reducing the frequency and severity of falls remains an important, complementary strategy for reducing fracture risk.', 2),
('f5000000-0000-0000-0000-000000000008', 'C', 'Addressing falls risk alone is sufficient, and bone health assessment adds no additional value', false, 'Ruled out because even with effective falls prevention, some falls will still occur, so ensuring bone strength through appropriate osteoporosis management remains important to reduce the consequences of any fall that does happen.', 3),
('f5000000-0000-0000-0000-000000000008', 'D', 'This combined approach is only relevant for younger patients, not older adults', false, 'Ruled out because this integrated approach is specifically most relevant and evidence-based in older adults, who carry the highest combined burden of both falls risk and osteoporosis-related fragility fracture risk.', 4),
('f5000000-0000-0000-0000-000000000008', 'E', 'Falls and osteoporosis interact to determine overall fracture risk, so addressing both reduces the likelihood and severity of future fragility fractures', true, 'Correct. Falls provide the mechanical trigger for fracture, while osteoporosis determines bone fragility; addressing both falls risk (reducing the likelihood of falling) and bone health (reducing fracture risk if a fall does occur) together provides a more comprehensive approach to reducing overall fragility fracture risk than addressing either factor alone.', 5),
('f5000000-0000-0000-0000-000000000009', 'A', 'Automatic maximal escalation of care to intensive care regardless of frailty or her wishes', false, $x$Ruled out because treatment decisions should be individualised based on likely benefit, burden and the patient's own wishes and values, not applied uniformly as maximal escalation regardless of these considerations.$x$, 1),
('f5000000-0000-0000-0000-000000000009', 'B', 'Automatic decision to withhold all escalation of care based on her age and frailty alone', false, 'Ruled out because decisions should not be based on age or frailty status alone without proper individualised assessment and consideration of her specific circumstances and wishes; blanket assumptions based on demographic factors are not appropriate.', 2),
('f5000000-0000-0000-0000-000000000009', 'C', 'A shared decision-making discussion considering her frailty, comorbidities, likely prognosis, and her own (or previously expressed, or family-represented) wishes and values', true, 'Correct. Decisions about treatment escalation in severely frail older adults should involve a shared decision-making process, considering her overall frailty and prognosis, the likely burdens and benefits of different treatment intensities, and her own wishes and values (directly if she has capacity, or through advance care planning documentation/family understanding of her wishes if she does not), rather than being based on age or frailty status alone.', 3),
('f5000000-0000-0000-0000-000000000009', 'D', 'The decision should be made unilaterally by the medical team without any discussion with the patient or family', false, 'Ruled out because shared decision-making, involving the patient (where possible) and family/those who know her wishes, is the appropriate approach, not a unilateral medical decision made without this input.', 4),
('f5000000-0000-0000-0000-000000000009', 'E', 'No discussion is needed until she actually deteriorates further', false, $x$Ruled out because proactive discussion about goals of care and treatment escalation, ideally before acute deterioration occurs, allows for better-informed, less rushed decision-making that can genuinely reflect the patient's wishes.$x$, 5),
('f5000000-0000-0000-0000-000000000010', 'A', 'Electronic frailty index (eFI) using routinely collected primary care data', true, 'Correct. The electronic frailty index uses routinely collected primary care electronic health record data (based on the presence of specific deficits/conditions) to automatically categorise patients into fit, mild, moderate or severe frailty categories, providing a practical, scalable population-level frailty screening tool without requiring additional in-person assessment for initial identification.', 1),
('f5000000-0000-0000-0000-000000000010', 'B', 'Full comprehensive geriatric assessment for every patient in primary care as the initial screening step', false, 'Ruled out because comprehensive geriatric assessment, while valuable, is time- and resource-intensive and is more appropriately targeted at patients already identified as frail (e.g. via a screening tool like the eFI) rather than being used as the initial universal screening step for the whole population.', 2),
('f5000000-0000-0000-0000-000000000010', 'C', 'Random blood glucose testing alone as a frailty screening tool', false, 'Ruled out because blood glucose testing assesses diabetic control, not frailty status; it is not a validated frailty screening tool.', 3),
('f5000000-0000-0000-0000-000000000010', 'D', 'Chest X-ray as a routine frailty screening tool', false, 'Ruled out because chest X-ray has no established role as a frailty screening tool.', 4),
('f5000000-0000-0000-0000-000000000010', 'E', 'No screening tools exist for frailty in primary care', false, 'Ruled out because validated tools, including the electronic frailty index, specifically exist and are used for frailty identification in the primary care setting.', 5),
('f5000000-0000-0000-0000-000000000011', 'A', 'Delirium', true, 'Correct. Acute onset of confusion with fluctuating attention and consciousness, disorientation, and perceptual disturbances (hallucinations), developing over hours to days in the context of an acute precipitant (here, infection) in a previously cognitively normal patient, is characteristic of delirium.', 1),
('f5000000-0000-0000-0000-000000000011', 'B', 'Dementia', false, 'Ruled out because dementia involves a gradual, progressive cognitive decline over months to years, not this acute, fluctuating presentation developing over 24 hours in a previously normal patient.', 2),
('f5000000-0000-0000-0000-000000000011', 'C', 'Depression', false, 'Ruled out because depression does not typically cause this acute onset of fluctuating attention, disorientation and hallucinations; the clinical picture here is specific to delirium.', 3),
('f5000000-0000-0000-0000-000000000011', 'D', 'Normal ageing', false, 'Ruled out because this acute, fluctuating confusional state with hallucinations is not a normal ageing process; it represents a significant, treatable acute medical condition (delirium) requiring identification and treatment of the underlying cause.', 4),
('f5000000-0000-0000-0000-000000000011', 'E', 'Chronic subdural haematoma', false, 'Ruled out because although this can cause confusion, the specific acute onset with fluctuation and clear temporal relationship to an acute infective illness is most consistent with delirium; a chronic subdural typically has a more insidious onset, though it remains an important differential to consider if delirium does not resolve with treatment of the underlying cause.', 5),
('f5000000-0000-0000-0000-000000000012', 'A', 'Mini-Mental State Examination', false, 'Ruled out because the MMSE is a general cognitive screening tool assessing overall cognitive function, not a specific delirium diagnostic screening tool based on this particular combination of core features.', 1),
('f5000000-0000-0000-0000-000000000012', 'B', 'Abbreviated Mental Test Score', false, 'Ruled out because the AMTS is a brief general cognitive screening tool, not the specific structured delirium diagnostic algorithm described here.', 2),
('f5000000-0000-0000-0000-000000000012', 'C', 'Geriatric Depression Scale', false, 'Ruled out because this tool screens for depression, not delirium, and does not use this specific combination of acute onset, fluctuation, inattention and altered consciousness/disorganised thinking criteria.', 3),
('f5000000-0000-0000-0000-000000000012', 'D', 'Clock drawing test', false, 'Ruled out because the clock drawing test is a screening tool for visuospatial and executive cognitive function (often used in dementia assessment), not the specific structured delirium diagnostic tool described here.', 4),
('f5000000-0000-0000-0000-000000000012', 'E', 'Confusion Assessment Method (CAM)', true, 'Correct. The Confusion Assessment Method is a widely used, validated screening tool for delirium, requiring the presence of acute onset with fluctuating course AND inattention, plus either disorganised thinking OR altered level of consciousness, to support a diagnosis of delirium.', 5),
('f5000000-0000-0000-0000-000000000013', 'A', 'Immediate physical restraint as the first-line management, without considering medication', false, 'Ruled out because physical restraint carries significant risks (including worsening agitation, injury) and is not the appropriate first-line pharmacological alternative; when medication is needed, cautious use of a low-dose antipsychotic is generally preferred over restraint where possible.', 1),
('f5000000-0000-0000-0000-000000000013', 'B', 'Consider a low-dose antipsychotic (e.g. haloperidol) only if non-pharmacological measures have failed and there is significant risk to the patient or others', true, 'Correct. Non-pharmacological measures remain first-line for managing delirium-related agitation; if these are insufficient and there is significant risk (as described here), a low dose of an antipsychotic such as haloperidol may be considered short-term, using the lowest effective dose for the shortest necessary duration, while continuing to identify and treat the underlying cause.', 2),
('f5000000-0000-0000-0000-000000000013', 'C', 'High-dose benzodiazepine as first-line pharmacological treatment', false, 'Ruled out because benzodiazepines can worsen delirium (except in specific contexts such as alcohol withdrawal-related delirium) and are not generally first-line for managing delirium-related agitation; low-dose antipsychotics are typically preferred when medication is required.', 3),
('f5000000-0000-0000-0000-000000000013', 'D', 'No intervention at all, despite the described risk to the patient', false, 'Ruled out because significant risk to the patient (e.g. removing lines needed for treatment) warrants active intervention, having already tried non-pharmacological measures, not simply continued observation without any action.', 4),
('f5000000-0000-0000-0000-000000000013', 'E', 'Long-term regular antipsychotic treatment established at this point, to be continued indefinitely', false, 'Ruled out because pharmacological treatment for delirium-related agitation should be short-term and reviewed regularly, aiming to stop once the acute delirium resolves, not established as an indefinite long-term treatment at this stage.', 5),
('f5000000-0000-0000-0000-000000000014', 'A', 'Delirium', false, 'Ruled out because delirium has an acute onset with fluctuating course, not this gradual, progressive decline over two years described here.', 1),
('f5000000-0000-0000-0000-000000000014', 'B', 'Vascular dementia', false, $x$Ruled out because vascular dementia classically shows a stepwise decline related to discrete cerebrovascular events, rather than the smooth, gradual progression described here, which is more typical of Alzheimer's disease.$x$, 2),
('f5000000-0000-0000-0000-000000000014', 'C', $x$Alzheimer's disease$x$, true, $x$Correct. Gradual, progressive decline in memory (particularly short-term/recent memory), language (word-finding difficulty) and visuospatial function (getting lost), evolving over years without the acute onset or fluctuation of delirium, is characteristic of Alzheimer's disease, the most common cause of dementia.$x$, 3),
('f5000000-0000-0000-0000-000000000014', 'D', 'Normal age-related memory changes', false, 'Ruled out because the degree and progressive nature of the impairment described (affecting daily function, word-finding, navigation) exceeds what would be expected from normal ageing and represents a pathological dementia process.', 4),
('f5000000-0000-0000-0000-000000000014', 'E', 'Frontotemporal dementia', false, $x$Ruled out because frontotemporal dementia typically presents with prominent early behavioural or language changes (rather than primarily memory impairment as the earliest feature) and often occurs at a younger age than typical for Alzheimer's disease.$x$, 5),
('f5000000-0000-0000-0000-000000000015', 'A', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease typically shows a smooth, gradual decline rather than this stepwise pattern tied to discrete vascular events, and does not typically cause focal neurological signs.$x$, 1),
('f5000000-0000-0000-0000-000000000015', 'B', 'Lewy body dementia', false, 'Ruled out because Lewy body dementia is characterised by fluctuating cognition, visual hallucinations and parkinsonism, not this specific stepwise pattern linked to discrete cerebrovascular events.', 2),
('f5000000-0000-0000-0000-000000000015', 'C', 'Frontotemporal dementia', false, 'Ruled out because frontotemporal dementia typically presents with prominent behavioural or language changes with a gradual progressive course, not this stepwise pattern linked to vascular events with focal neurological signs.', 3),
('f5000000-0000-0000-0000-000000000015', 'D', 'Vascular dementia', true, 'Correct. A stepwise pattern of cognitive decline, with discrete episodes of sudden worsening corresponding to identified cerebrovascular events, and focal neurological signs on examination, is characteristic of vascular dementia, resulting from cumulative cerebral damage from strokes or chronic small vessel disease.', 4),
('f5000000-0000-0000-0000-000000000015', 'E', 'Normal-pressure hydrocephalus', false, 'Ruled out because NPH classically presents with the triad of gait disturbance, urinary incontinence and cognitive decline, without the stepwise pattern tied to discrete cerebrovascular events and focal signs described here.', 5),
('f5000000-0000-0000-0000-000000000016', 'A', 'Dementia with Lewy bodies', true, $x$Correct. The combination of fluctuating cognition, recurrent detailed visual hallucinations, spontaneous parkinsonism (not preceded by a long history of isolated motor Parkinson's disease), and REM sleep behaviour disorder is characteristic of dementia with Lewy bodies, distinguishing it from Parkinson's disease dementia (where a long-standing motor disorder typically precedes dementia by at least a year) and from Alzheimer's disease.$x$, 1),
('f5000000-0000-0000-0000-000000000016', 'B', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease does not typically cause prominent early visual hallucinations, spontaneous parkinsonism, or REM sleep behaviour disorder; these features are much more specific to Lewy body dementia.$x$, 2),
('f5000000-0000-0000-0000-000000000016', 'C', $x$Parkinson's disease dementia$x$, false, $x$Ruled out because Parkinson's disease dementia specifically requires a well-established motor Parkinson's disease diagnosis for at least a year before dementia onset, whereas here the parkinsonism and cognitive/hallucinatory features appear to emerge together, more consistent with dementia with Lewy bodies.$x$, 3),
('f5000000-0000-0000-0000-000000000016', 'D', 'Delirium', false, 'Ruled out because although hallucinations and fluctuation occur in both conditions, the chronic, progressive nature of this presentation (rather than an acute, reversible precipitant-driven episode) points to dementia with Lewy bodies rather than delirium, though delirium should always be considered and excluded/treated if a precipitant is present, as it can also complicate Lewy body dementia.', 4),
('f5000000-0000-0000-0000-000000000016', 'E', 'Frontotemporal dementia', false, 'Ruled out because frontotemporal dementia is characterised by early behavioural or language changes, not the specific triad of fluctuating cognition, visual hallucinations and spontaneous parkinsonism seen here.', 5),
('f5000000-0000-0000-0000-000000000017', 'A', 'Antipsychotics are entirely safe and can be used without any specific caution in this population', false, 'Ruled out because this significantly understates the genuine, well-documented risk of severe adverse reactions to antipsychotics specifically in dementia with Lewy bodies, requiring particular caution not needed to the same degree in other dementia types.', 1),
('f5000000-0000-0000-0000-000000000017', 'B', 'Antipsychotics should never be used under any circumstances in this patient, regardless of symptom severity', false, 'Ruled out because although extreme caution is required, in situations of severe, distressing symptoms not responding to other measures, cautious use of specific atypical antipsychotics with specialist input may sometimes still be considered, rather than an absolute prohibition in all circumstances.', 2),
('f5000000-0000-0000-0000-000000000017', 'C', 'This risk applies equally to all types of dementia, with no particular concern specific to Lewy body dementia', false, 'Ruled out because the risk of severe neuroleptic sensitivity reactions is specifically and disproportionately associated with dementia with Lewy bodies compared with other dementia types, making this an important, specific prescribing consideration rather than a generic dementia-wide concern.', 3),
('f5000000-0000-0000-0000-000000000017', 'D', 'Patients with dementia with Lewy bodies have a high risk of severe, potentially life-threatening neuroleptic sensitivity reactions to antipsychotics, particularly first-generation agents, requiring extreme caution and specialist input if antipsychotics are considered necessary', true, 'Correct. Dementia with Lewy bodies carries a specific, well-recognised risk of severe neuroleptic sensitivity reactions (marked worsening of parkinsonism, sedation, autonomic instability, and increased mortality) to antipsychotic medication, particularly typical (first-generation) agents; if antipsychotic treatment is felt to be essential, it requires extreme caution, specialist input, and use of an atypical agent with the lowest possible risk profile at the lowest effective dose.', 4),
('f5000000-0000-0000-0000-000000000017', 'E', 'Only benzodiazepines, not antipsychotics, carry any risk in this population', false, 'Ruled out because although benzodiazepines also require caution in older adults with dementia generally, the specific, well-documented severe risk relevant here relates to antipsychotic use in Lewy body dementia specifically.', 5),
('f5000000-0000-0000-0000-000000000018', 'A', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease typically presents with prominent early memory impairment as the leading symptom, rather than this pattern of early, predominant personality and behavioural change with relatively preserved memory.$x$, 1),
('f5000000-0000-0000-0000-000000000018', 'B', 'Vascular dementia', false, 'Ruled out because there is no described stepwise decline or evidence of cerebrovascular events; the presentation described (early personality change, disinhibition) is more characteristic of frontotemporal dementia.', 2),
('f5000000-0000-0000-0000-000000000018', 'C', 'Dementia with Lewy bodies', false, 'Ruled out because Lewy body dementia is characterised by fluctuating cognition, visual hallucinations and parkinsonism, not primarily this pattern of early personality/behavioural change with relatively preserved memory.', 3),
('f5000000-0000-0000-0000-000000000018', 'D', 'Normal personality change with age', false, 'Ruled out because this represents a significant, progressive pathological change in personality and behaviour with functional impact, not a normal ageing process.', 4),
('f5000000-0000-0000-0000-000000000018', 'E', 'Frontotemporal dementia', true, 'Correct. Early, prominent personality and behavioural change (disinhibition, loss of social appropriateness, lack of insight/concern), with relative preservation of memory and visuospatial function early on, and onset at a relatively younger age, is characteristic of frontotemporal dementia (behavioural variant), reflecting predominant frontal and temporal lobe involvement.', 5),
('f5000000-0000-0000-0000-000000000019', 'A', $x$Alzheimer's disease$x$, false, $x$Ruled out because Alzheimer's disease does not typically cause this specific gait disturbance and urinary incontinence pattern this early, or the disproportionate ventricular enlargement on imaging described here.$x$, 1),
('f5000000-0000-0000-0000-000000000019', 'B', 'Normal pressure hydrocephalus', true, $x$Correct. The classic triad of gait disturbance (typically broad-based, 'magnetic' or shuffling), urinary incontinence and cognitive decline, with ventricular enlargement disproportionate to cortical atrophy on imaging, is characteristic of normal pressure hydrocephalus, an important potentially reversible cause of dementia-like symptoms, sometimes improving with CSF shunting.$x$, 2),
('f5000000-0000-0000-0000-000000000019', 'C', 'Vascular dementia', false, 'Ruled out because although gait disturbance can occur in vascular dementia, the specific triad and disproportionate ventriculomegaly pattern described here is more classic for normal pressure hydrocephalus.', 3),
('f5000000-0000-0000-0000-000000000019', 'D', $x$Parkinson's disease$x$, false, $x$Ruled out because although Parkinson's disease causes gait disturbance, it does not typically cause this specific triad including early urinary incontinence and the described disproportionate ventricular enlargement pattern on imaging.$x$, 4),
('f5000000-0000-0000-0000-000000000019', 'E', 'Simple age-related gait decline unrelated to a specific diagnosis', false, 'Ruled out because the specific combination of the classic triad with the described imaging findings represents a recognised, potentially treatable diagnosis (NPH), not simply non-specific age-related decline.', 5),
('f5000000-0000-0000-0000-000000000020', 'A', 'Routine use of sedative medication to prevent agitation before it develops', false, 'Ruled out because prophylactic sedative use is not a recommended delirium prevention strategy and can, in fact, increase delirium risk rather than reduce it.', 1),
('f5000000-0000-0000-0000-000000000020', 'B', 'Minimising family and visitor involvement to reduce overstimulation', false, 'Ruled out because involving familiar people (family, carers) is generally protective and recommended as part of delirium prevention, through reorientation and reducing distress, rather than being restricted.', 2),
('f5000000-0000-0000-0000-000000000020', 'C', 'Ensuring adequate hydration, pain control, sensory aid provision (glasses/hearing aids), and regular reorientation with clocks/calendars', true, 'Correct. Multicomponent non-pharmacological interventions -- including maintaining adequate hydration and nutrition, effective pain management, ensuring patients have their glasses and hearing aids, promoting normal sleep-wake cycles, minimising unnecessary ward moves, and regular reorientation (clocks, calendars, familiar faces) -- have been shown to reduce delirium incidence in at-risk hospitalised patients.', 3),
('f5000000-0000-0000-0000-000000000020', 'D', 'Keeping the patient in a dark, quiet room at all times, day and night', false, 'Ruled out because maintaining a normal day-night cycle (light during the day, dark and quiet at night) supports normal sleep-wake patterns; keeping the room dark at all times would disrupt this and is not a recommended strategy.', 4),
('f5000000-0000-0000-0000-000000000020', 'E', 'No specific preventive measures exist for delirium; it can only be treated once it occurs', false, 'Ruled out because evidence-based, multicomponent non-pharmacological preventive strategies do exist and are recommended, particularly for at-risk hospitalised older patients such as this one following hip fracture.', 5),
('f5000000-0000-0000-0000-000000000021', 'A', 'Stopping all medications immediately without individual review', false, 'Ruled out because abruptly stopping all medications without individual assessment could cause harm from withdrawal effects or loss of disease control for conditions where treatment remains beneficial; a structured, individualised review is required instead.', 1),
('f5000000-0000-0000-0000-000000000021', 'B', 'A structured medication review considering the indication, benefit, harm and appropriateness of each medication in the context of her overall goals of care', true, $x$Correct. A structured polypharmacy review systematically examines each medication's ongoing indication, evidence of benefit, potential for harm/interactions, and appropriateness given her overall clinical context, prognosis and personal goals, forming the basis for informed decisions about continuing, adjusting or stopping (deprescribing) individual medications.$x$, 2),
('f5000000-0000-0000-0000-000000000021', 'C', 'Simply reducing the number of tablets by stopping the most recently started medication only', false, $x$Ruled out because medication review should be based on clinical assessment of each drug's ongoing appropriateness, not simply the order in which medications were started.$x$, 3),
('f5000000-0000-0000-0000-000000000021', 'D', 'No review is needed, as more medications is always better for treating multiple comorbidities', false, 'Ruled out because polypharmacy carries recognised risks (interactions, adverse effects, reduced adherence, increased falls risk), making structured review important rather than assuming more medication is inherently beneficial.', 4),
('f5000000-0000-0000-0000-000000000021', 'E', 'Referral for medication review only if she specifically requests it', false, 'Ruled out because proactive medication review is recommended for patients with significant polypharmacy, particularly in the context of frailty or multimorbidity, rather than waiting for the patient to specifically request it.', 5),
('f5000000-0000-0000-0000-000000000022', 'A', 'Cumulative anticholinergic burden from multiple medications with anticholinergic effects', true, 'Correct. Amitriptyline, oxybutynin and chlorphenamine all have anticholinergic properties; when combined, their cumulative anticholinergic burden can cause confusion, dry mouth, blurred vision, constipation and urinary retention, particularly in older adults who are more susceptible to these effects, and is a recognised, modifiable contributor to cognitive impairment and falls risk.', 1),
('f5000000-0000-0000-0000-000000000022', 'B', 'Coincidental, unrelated development of dementia', false, 'Ruled out because the specific combination of anticholinergic symptoms (confusion, dry mouth, blurred vision, constipation) occurring with multiple anticholinergic medications points to a drug-related cause, which should be addressed before attributing symptoms to a new diagnosis of dementia.', 2),
('f5000000-0000-0000-0000-000000000022', 'C', 'Simple dehydration unrelated to medication', false, 'Ruled out because although dehydration can cause some overlapping symptoms, the specific combination of symptoms and the presence of multiple anticholinergic medications points to cumulative anticholinergic burden as the more likely, directly modifiable cause.', 3),
('f5000000-0000-0000-0000-000000000022', 'D', 'Normal age-related decline requiring no specific action', false, 'Ruled out because this symptom pattern reflects a specific, recognised and modifiable drug-related cause, not simply normal ageing that would not respond to medication review.', 4),
('f5000000-0000-0000-0000-000000000022', 'E', 'An allergic reaction to one of his medications', false, 'Ruled out because this symptom pattern (confusion, dry mouth, blurred vision, constipation) reflects the pharmacological, cumulative anticholinergic effect of multiple drugs, not an allergic hypersensitivity reaction.', 5),
('f5000000-0000-0000-0000-000000000023', 'A', 'APGAR score', false, 'Ruled out because the APGAR score is a neonatal assessment tool used immediately after birth, entirely unrelated to medication review in older adults.', 1),
('f5000000-0000-0000-0000-000000000023', 'B', 'Glasgow Coma Scale', false, 'Ruled out because the Glasgow Coma Scale assesses level of consciousness, not medication appropriateness.', 2),
('f5000000-0000-0000-0000-000000000023', 'C', 'CHA2DS2-VASc score', false, 'Ruled out because this tool assesses stroke risk in atrial fibrillation to guide anticoagulation decisions, not a general structured medication appropriateness review tool.', 3),
('f5000000-0000-0000-0000-000000000023', 'D', 'Waterlow score', false, 'Ruled out because the Waterlow score assesses pressure ulcer risk, not medication appropriateness.', 4),
('f5000000-0000-0000-0000-000000000023', 'E', 'STOPP/START criteria', true, $x$Correct. STOPP (Screening Tool of Older People's potentially inappropriate Prescriptions) and START (Screening Tool to Alert to Right Treatment) are validated, structured tools specifically designed to identify potentially inappropriate medications that should be considered for stopping (STOPP) and potentially beneficial medications that may be missing and should be considered for starting (START) in older adults.$x$, 5),
('f5000000-0000-0000-0000-000000000024', 'A', 'Continue all medications indefinitely regardless of prognosis, as stopping any medication is always harmful', false, 'Ruled out because this fails to account for the changing risk-benefit balance of long-term preventive medications in the context of significantly limited life expectancy, where such medications are unlikely to provide meaningful benefit and may add unnecessary burden.', 1),
('f5000000-0000-0000-0000-000000000024', 'B', 'Stop all medications immediately without any individual consideration or discussion', false, 'Ruled out because deprescribing decisions should still be individualised and, where possible, discussed with the patient/family, rather than applying a blanket stop to all medications without consideration of which remain appropriate (e.g. symptom-focused medications would generally be continued).', 2),
('f5000000-0000-0000-0000-000000000024', 'C', 'Add further preventive medications to optimise long-term risk reduction', false, 'Ruled out because adding further long-term preventive medications is not appropriate in this context of very limited life expectancy, where the priority shifts towards symptom control and quality of life rather than long-term risk reduction.', 3),
('f5000000-0000-0000-0000-000000000024', 'D', 'Consider deprescribing medications where the time to benefit exceeds his likely remaining life expectancy, or where the burden outweighs any realistic benefit', true, $x$Correct. In patients with significantly limited life expectancy, preventive medications with a long time-to-benefit (such as statins for primary prevention or bisphosphonates) are unlikely to provide meaningful benefit within the person's remaining lifetime and may be appropriately deprescribed, reducing pill burden and potential side effects, as part of a person-centred approach focused on quality of life and current comfort.$x$, 4),
('f5000000-0000-0000-0000-000000000024', 'E', 'Refer for further invasive investigations to optimise his cardiovascular risk profile', false, 'Ruled out because this would not be an appropriate use of resources or aligned with his likely goals of care given his advanced dementia and very limited life expectancy; the focus should be on medication appropriateness and comfort, not further risk-factor investigation.', 5),
('f5000000-0000-0000-0000-000000000025', 'A', 'Add a further antihypertensive to better control his blood pressure', false, 'Ruled out because adding further antihypertensive medication would likely worsen his postural hypotension and falls risk, the opposite of the appropriate response to this presentation.', 1),
('f5000000-0000-0000-0000-000000000025', 'B', 'No changes are needed, as blood pressure control always takes priority over falls risk', false, 'Ruled out because in older adults, particularly with symptomatic postural hypotension, individualised balancing of blood pressure control against falls and other risks is appropriate, rather than rigidly prioritising blood pressure targets over safety.', 2),
('f5000000-0000-0000-0000-000000000025', 'C', 'Review and consider reducing or stopping antihypertensive medications, balancing blood pressure control against falls risk', true, 'Correct. In an older adult with symptomatic postural hypotension and falls risk on multiple antihypertensives, the medication regimen should be reviewed, considering whether blood pressure targets and medication burden remain appropriate, balancing the benefits of blood pressure control against the significant risks of falls and their consequences in this population.', 3),
('f5000000-0000-0000-0000-000000000025', 'D', 'Stop all his medications immediately without a structured review', false, 'Ruled out because abrupt cessation of all medications without individualised review could cause harm; a structured, considered approach to adjusting his antihypertensive regimen is more appropriate.', 4),
('f5000000-0000-0000-0000-000000000025', 'E', 'Refer for permanent pacemaker insertion as the first step', false, 'Ruled out because there is no indication of a bradyarrhythmia requiring pacing; his symptoms are attributed to medication-related postural hypotension, which should first be addressed through medication review.', 5),
('f5000000-0000-0000-0000-000000000026', 'A', 'Relax her glycaemic target and consider reducing her diabetes medication to reduce hypoglycaemia risk', true, 'Correct. In older adults, particularly with cognitive impairment or frailty, tight glycaemic control carries a disproportionate risk of hypoglycaemia (with associated risks of falls, confusion and cardiovascular events) relative to the modest long-term microvascular benefit; relaxing glycaemic targets and adjusting medication accordingly is appropriate to prioritise safety over intensive control.', 1),
('f5000000-0000-0000-0000-000000000026', 'B', 'Intensify her diabetes treatment further to tighten glycaemic control', false, 'Ruled out because this would increase, not reduce, her hypoglycaemia risk, which is already a significant concern; intensifying treatment further would be inappropriate and potentially harmful in this context.', 2),
('f5000000-0000-0000-0000-000000000026', 'C', 'No changes are needed, as tight glycaemic control is always the priority regardless of hypoglycaemia risk', false, 'Ruled out because individualised glycaemic targets, accounting for hypoglycaemia risk, cognitive status and overall frailty, are recommended in older adults rather than uniformly pursuing tight control regardless of these risks.', 3),
('f5000000-0000-0000-0000-000000000026', 'D', 'Stop all diabetes medication immediately without any structured plan', false, 'Ruled out because abrupt cessation without a structured plan could risk hyperglycaemia; a considered adjustment of her regimen, balancing risks appropriately, is the more suitable approach.', 4),
('f5000000-0000-0000-0000-000000000026', 'E', 'Refer immediately for insulin pump therapy to improve control precision', false, 'Ruled out because this would not address the core issue (excessive intensity of glycaemic control relative to her individual risk-benefit balance) and is not the appropriate response to recurrent hypoglycaemia in this context.', 5),
('f5000000-0000-0000-0000-000000000027', 'A', 'There is no genuine safety concern in this scenario', false, 'Ruled out because this represents a genuine, well-recognised patient safety risk (a significant drug interaction that could have been identified through proper medication reconciliation), not a benign scenario without concern.', 1),
('f5000000-0000-0000-0000-000000000027', 'B', 'The only issue is that trimethoprim was the wrong first-line choice for a UTI in general', false, 'Ruled out because although alternative antibiotics might be considered, the primary safety issue highlighted by this scenario is the failure to check for interactions with his existing medication (warfarin), not simply the general choice of antibiotic class.', 2),
('f5000000-0000-0000-0000-000000000027', 'C', 'This scenario demonstrates good practice with no changes needed', false, 'Ruled out because failing to cross-check medications before prescribing a new interacting drug represents a patient safety gap, not an example of good practice to be maintained without change.', 3),
('f5000000-0000-0000-0000-000000000027', 'D', 'Inadequate medication reconciliation across care settings can lead to dangerous drug interactions being missed', true, $x$Correct. This scenario highlights the risk of inadequate medication reconciliation when care is provided across different settings or by different prescribers without full access to or review of the patient's complete medication list, here risking a significant, recognised interaction (trimethoprim potentiating warfarin's effect, raising INR and bleeding risk) that could have been identified and avoided with proper cross-checking.$x$, 4),
('f5000000-0000-0000-0000-000000000027', 'E', 'The concern relates only to renal function, not to any drug interaction', false, 'Ruled out because although renal function is relevant to antibiotic dosing generally, the specific, significant concern highlighted by this scenario relates to the trimethoprim-warfarin interaction risking a dangerously raised INR, not primarily a renal function issue.', 5),
('f5000000-0000-0000-0000-000000000028', 'A', 'A simple coincidence with no recognised underlying pattern or specific term', false, 'Ruled out because this is a well-recognised phenomenon in geriatric prescribing (prescribing cascade/indication creep), not simply a random coincidence without an identifiable pattern or explanation.', 1),
('f5000000-0000-0000-0000-000000000028', 'B', 'Deliberate, appropriate escalation of treatment intensity by design', false, 'Ruled out because this scenario describes an unintended accumulation of medications over time, often without full ongoing review, rather than a deliberately planned, coordinated escalation of treatment.', 2),
('f5000000-0000-0000-0000-000000000028', 'C', 'A sign that she is receiving excellent, well-coordinated care', false, 'Ruled out because the scenario specifically describes fragmentation (multiple specialists without full visibility of her complete regimen, unclear original indications), which represents a risk to safe, well-coordinated care rather than an example of it.', 3),
('f5000000-0000-0000-0000-000000000028', 'D', 'An unavoidable, unmodifiable consequence of ageing that cannot be addressed', false, 'Ruled out because although complex comorbidity is common in older age, the specific issue of unreviewed prescribing cascades and fragmented medication oversight is a modifiable systems issue that can be addressed through structured medication review, not an inevitable, unaddressable consequence of age itself.', 4),
('f5000000-0000-0000-0000-000000000028', 'E', 'A prescribing cascade, where new medications are added over time (sometimes to treat side effects of existing drugs) without adequate ongoing review of the original indications', true, 'Correct. A prescribing cascade occurs when a new medication is started to treat a symptom or side effect caused by an existing medication (which may be misinterpreted as a new medical condition), without recognising the underlying iatrogenic cause, and can also more broadly reflect accumulation of medications over time across multiple prescribers without adequate periodic review of original indications, both of which contribute to increasingly complex polypharmacy over time.', 5),
('f5000000-0000-0000-0000-000000000029', 'A', 'Stopping all medications to eliminate the need for any adherence support', false, 'Ruled out because this does not represent an appropriate practical adherence solution; it would inappropriately discontinue potentially beneficial medications rather than supporting safe administration of an appropriately reviewed regimen.', 1),
('f5000000-0000-0000-0000-000000000029', 'B', 'Increasing the number of different medications to simplify his routine', false, 'Ruled out because increasing the number of medications would make adherence more, not less, challenging; simplifying the regimen (where clinically appropriate) alongside adherence aids is the more suitable approach.', 2),
('f5000000-0000-0000-0000-000000000029', 'C', 'A multi-compartment dosette box (pill organiser) with doses pre-sorted by day and time', true, 'Correct. A multi-compartment dosette box, with medications pre-sorted into compartments by day and time of dosing (often prepared by a pharmacy), is a practical, commonly used strategy to support medication adherence in patients who struggle with complex regimens, reducing the risk of missed or duplicated doses.', 3),
('f5000000-0000-0000-0000-000000000029', 'D', $x$Relying solely on the patient's memory without any practical aids$x$, false, 'Ruled out because this does not address the adherence difficulty described; practical aids specifically exist to support patients who struggle with memory or organisation of complex regimens.', 4),
('f5000000-0000-0000-0000-000000000029', 'E', 'Requiring him to attend hospital daily for medication administration', false, 'Ruled out because this is a disproportionate, resource-intensive response when simpler, practical community-based solutions (such as a dosette box) are available and appropriate for this level of difficulty.', 5),
('f5000000-0000-0000-0000-000000000030', 'A', 'Simple age-related decline in renal function unrelated to her medications', false, 'Ruled out because the specific, well-recognised risk of this three-drug combination provides a clear, likely explanation for her acute (not simply chronic age-related) kidney injury, which should be actively considered rather than attributed to age alone.', 1),
('f5000000-0000-0000-0000-000000000030', 'B', $x$The combination of an NSAID, ACE inhibitor and diuretic ('triple whammy') impairing renal perfusion and function$x$, true, $x$Correct. The combination of an NSAID (reducing prostaglandin-mediated afferent arteriolar dilation), an ACE inhibitor (reducing efferent arteriolar constriction) and a diuretic (causing volume depletion) together significantly impair the kidney's ability to maintain glomerular filtration, particularly in situations of reduced renal perfusion, precipitating acute kidney injury -- a combination sometimes termed the 'triple whammy.'$x$, 2),
('f5000000-0000-0000-0000-000000000030', 'C', 'Direct toxic effect of the diuretic alone, unrelated to the other medications', false, 'Ruled out because although diuretics contribute to volume depletion, the specific, well-recognised risk relates to the interaction of all three drug classes together, not the diuretic in isolation.', 3),
('f5000000-0000-0000-0000-000000000030', 'D', 'Urinary tract infection as the primary cause', false, 'Ruled out because there is no specific evidence of infection described; the clear pharmacological explanation from this recognised high-risk drug combination is the more likely cause here.', 4),
('f5000000-0000-0000-0000-000000000030', 'E', 'Coincidental, unrelated renal artery stenosis', false, $x$Ruled out because although renal artery stenosis is a differential to consider (and would itself be exacerbated by this drug combination), the well-recognised 'triple whammy' interaction provides a clear, directly relevant explanation without needing to invoke a separate coincidental diagnosis.$x$, 5),
('f5000000-0000-0000-0000-000000000031', 'A', 'No further investigation needed, as this is a normal consequence of a minor fall', false, 'Ruled out because a fracture from a low-energy fall (from standing height or less) is, by definition, a fragility fracture suggesting underlying reduced bone strength, warranting further assessment rather than being dismissed as an expected outcome of a trivial injury.', 1),
('f5000000-0000-0000-0000-000000000031', 'B', 'Immediate bisphosphonate treatment without any assessment', false, 'Ruled out because although bone-protective treatment is often appropriate following a fragility fracture, an assessment (DEXA and/or fracture risk tool) is generally used to confirm the diagnosis and guide the most appropriate specific treatment choice, rather than starting treatment blind without any assessment.', 2),
('f5000000-0000-0000-0000-000000000031', 'C', 'Referral for hip replacement surgery', false, 'Ruled out because this is a wrist (distal radius), not hip, fracture, and joint replacement is not the relevant management step here; the focus is on assessing and addressing underlying bone health.', 3),
('f5000000-0000-0000-0000-000000000031', 'D', 'Arrange a DEXA scan and formal fracture risk assessment', true, 'Correct. A low-trauma (fragility) fracture in a postmenopausal woman should prompt assessment for underlying osteoporosis, typically with a DEXA scan and/or a validated fracture risk assessment tool, to guide decisions about bone-protective treatment and reduce the risk of future fractures.', 4),
('f5000000-0000-0000-0000-000000000031', 'E', 'Reassurance only, with no follow-up required', false, 'Ruled out because a fragility fracture is a significant sentinel event indicating substantially increased risk of future fractures, warranting proper assessment and follow-up, not simple reassurance without further action.', 5),
('f5000000-0000-0000-0000-000000000032', 'A', 'Calcium supplementation alone, without a bone-specific agent', false, 'Ruled out because although adequate calcium and vitamin D intake is important as an adjunct, calcium supplementation alone is not sufficient treatment for confirmed osteoporosis with a fragility fracture; a bone-specific agent such as a bisphosphonate is needed.', 1),
('f5000000-0000-0000-0000-000000000032', 'B', 'Hormone replacement therapy as first-line treatment in all postmenopausal women with osteoporosis', false, 'Ruled out because although HRT can have bone-protective effects, it is not generally used as first-line osteoporosis treatment given its broader risk-benefit profile (e.g. breast cancer, cardiovascular risk); bisphosphonates are the standard first-line choice for most patients.', 2),
('f5000000-0000-0000-0000-000000000032', 'C', 'Long-term high-dose corticosteroids', false, 'Ruled out because corticosteroids actually worsen bone density and increase osteoporosis risk; they are not a treatment for osteoporosis.', 3),
('f5000000-0000-0000-0000-000000000032', 'D', 'Immediate surgical intervention', false, 'Ruled out because osteoporosis itself is managed medically; surgery would only be relevant for managing a specific fracture complication, not as treatment for the underlying bone disease.', 4),
('f5000000-0000-0000-0000-000000000032', 'E', 'Oral bisphosphonate (e.g. alendronic acid)', true, 'Correct. Oral bisphosphonates such as alendronic acid are first-line pharmacological treatment for postmenopausal osteoporosis, working by inhibiting osteoclast-mediated bone resorption, and have strong evidence for reducing both vertebral and non-vertebral fracture risk.', 5),
('f5000000-0000-0000-0000-000000000033', 'A', 'Take with food to reduce gastrointestinal side effects', false, 'Ruled out because taking bisphosphonates with food significantly reduces their absorption; they must be taken on an empty stomach for adequate efficacy.', 1),
('f5000000-0000-0000-0000-000000000033', 'B', 'Take on an empty stomach with a full glass of water, remaining upright for at least 30 minutes afterwards, before eating', true, 'Correct. Oral bisphosphonates such as alendronic acid must be taken on an empty stomach with a full glass of plain water, with the patient remaining upright (sitting or standing) for at least 30 minutes afterwards and before eating, to ensure adequate absorption and reduce the risk of oesophageal irritation/oesophagitis.', 2),
('f5000000-0000-0000-0000-000000000033', 'C', 'Take lying down to help swallow the tablet more easily', false, 'Ruled out because lying down after taking a bisphosphonate increases the risk of oesophageal reflux and irritation/oesophagitis; the patient should remain upright.', 3),
('f5000000-0000-0000-0000-000000000033', 'D', 'No specific timing or positioning precautions are needed', false, 'Ruled out because specific administration precautions (empty stomach, full glass of water, remaining upright) are essential both for adequate drug absorption and to reduce the risk of oesophageal adverse effects.', 4),
('f5000000-0000-0000-0000-000000000033', 'E', 'Take just before going to sleep for convenience', false, 'Ruled out because taking the medication before lying down for sleep increases the risk of oesophageal irritation; remaining upright after the dose is specifically required.', 5),
('f5000000-0000-0000-0000-000000000034', 'A', 'Atypical femoral fracture', true, $x$Correct. A transverse or short oblique subtrochanteric or femoral shaft fracture with minimal trauma, often preceded by prodromal thigh pain, and characteristic radiographic features (cortical thickening/'beaking'), occurring after long-term bisphosphonate use, is characteristic of atypical femoral fracture, a rare but recognised complication of prolonged bisphosphonate therapy from oversuppression of bone turnover.$x$, 1),
('f5000000-0000-0000-0000-000000000034', 'B', 'Typical osteoporotic femoral neck fracture', false, 'Ruled out because typical osteoporotic fractures occur at the femoral neck (not subtrochanteric/shaft) and show a different fracture pattern (usually oblique/spiral rather than transverse with cortical beaking), distinguishing them from this atypical presentation.', 2),
('f5000000-0000-0000-0000-000000000034', 'C', 'Pathological fracture from bone metastasis', false, 'Ruled out because although malignancy should always be considered in unusual fractures, the specific radiographic features (cortical thickening, transverse pattern) and clear context of long-term bisphosphonate use are classic for atypical femoral fracture rather than metastatic disease.', 3),
('f5000000-0000-0000-0000-000000000034', 'D', 'Simple stress fracture unrelated to medication', false, 'Ruled out because the specific radiographic appearance and strong association with prolonged bisphosphonate use point specifically to atypical femoral fracture, a recognised drug-related complication, rather than a generic stress fracture.', 4),
('f5000000-0000-0000-0000-000000000034', 'E', 'Osteomyelitis of the femur', false, 'Ruled out because there is no mention of infective features (fever, raised inflammatory markers), and the specific radiographic pattern described is characteristic of atypical femoral fracture, not infection.', 5),
('f5000000-0000-0000-0000-000000000035', 'A', 'Atrial fibrillation as a direct result of the dental procedure', false, 'Ruled out because although a rare association between bisphosphonates and atrial fibrillation has been noted in some studies, this is not the specific, well-recognised concern relevant to dental extraction procedures; osteonecrosis of the jaw is the relevant, procedure-specific risk.', 1),
('f5000000-0000-0000-0000-000000000035', 'B', 'Immediate anaphylaxis to local anaesthetic due to bisphosphonate use', false, 'Ruled out because bisphosphonates do not have a recognised interaction increasing anaphylaxis risk to local anaesthetics; this is not the relevant concern in this scenario.', 2),
('f5000000-0000-0000-0000-000000000035', 'C', 'Osteonecrosis of the jaw', true, 'Correct. Bisphosphonate-related osteonecrosis of the jaw is a rare but recognised complication, more strongly associated with high-dose IV bisphosphonate use in cancer patients but also occurring, less commonly, with oral bisphosphonate use, particularly around the time of invasive dental procedures such as extractions; risk assessment and appropriate precautions are considered before such procedures in patients on bisphosphonate therapy.', 3),
('f5000000-0000-0000-0000-000000000035', 'D', 'Increased risk of dental caries unrelated to healing', false, 'Ruled out because this is not the specific, recognised complication of concern regarding bisphosphonate use around invasive dental procedures; osteonecrosis of the jaw is the relevant risk.', 4),
('f5000000-0000-0000-0000-000000000035', 'E', 'Oesophageal stricture from the dental procedure itself', false, 'Ruled out because oesophageal irritation relates to bisphosphonate administration technique, not dental extraction; it is not the relevant concern in this specific clinical context.', 5),
('f5000000-0000-0000-0000-000000000036', 'A', 'No specific bone health assessment is needed, as his rheumatoid arthritis is the only relevant consideration', false, 'Ruled out because although rheumatoid arthritis itself is also a risk factor for osteoporosis, his significant, prolonged glucocorticoid exposure independently and substantially increases his fracture risk, warranting specific assessment and consideration of bone protection.', 1),
('f5000000-0000-0000-0000-000000000036', 'B', 'Bone protection is only relevant if he has already sustained a fracture', false, 'Ruled out because proactive risk assessment and consideration of bone-protective treatment is recommended given his significant ongoing steroid exposure, rather than waiting for a fracture to occur before taking action.', 2),
('f5000000-0000-0000-0000-000000000036', 'C', 'Simply stopping his prednisolone abruptly to reduce bone loss', false, 'Ruled out because abruptly stopping long-term steroids risks adrenal crisis and rheumatoid flare; steroid doses should be carefully managed (weaned if appropriate) rather than stopped abruptly, and bone protection addressed alongside continued necessary steroid treatment where needed.', 3),
('f5000000-0000-0000-0000-000000000036', 'D', 'Recommend high-dose steroid increase to better control his rheumatoid arthritis, with no consideration of bone health', false, 'Ruled out because this would further increase his glucocorticoid-related bone health risk without addressing the relevant bone protection consideration raised by his current exposure.', 4),
('f5000000-0000-0000-0000-000000000036', 'E', 'Assess his fracture risk and consider bone-protective treatment (e.g. a bisphosphonate) given his significant, ongoing glucocorticoid exposure', true, 'Correct. Long-term glucocorticoid use (particularly at doses of 7.5mg prednisolone or more daily, for 3 months or longer) is a major, independent risk factor for osteoporosis and fragility fracture; formal fracture risk assessment and consideration of bone-protective treatment (commonly a bisphosphonate) is recommended for patients on this level of ongoing steroid exposure, often without necessarily requiring a DEXA scan first in higher-risk individuals depending on local protocols.', 5),
('f5000000-0000-0000-0000-000000000037', 'A', 'No alternative treatment exists if oral bisphosphonates are not tolerated', false, 'Ruled out because effective alternative treatments (denosumab, IV bisphosphonates, and other agents depending on individual circumstances) do exist for patients unable to tolerate oral bisphosphonates.', 1),
('f5000000-0000-0000-0000-000000000037', 'B', 'High-dose calcium supplementation alone as a substitute for bone-specific therapy', false, 'Ruled out because calcium alone is not an adequate substitute for a bone-specific antiresorptive or anabolic agent in a patient with confirmed osteoporosis requiring active treatment.', 2),
('f5000000-0000-0000-0000-000000000037', 'C', 'Long-term NSAID therapy as an alternative osteoporosis treatment', false, 'Ruled out because NSAIDs have no role in osteoporosis treatment; they are not a recognised alternative to bisphosphonate therapy.', 3),
('f5000000-0000-0000-0000-000000000037', 'D', 'Denosumab (subcutaneous injection) or an intravenous bisphosphonate (e.g. zoledronic acid)', true, 'Correct. For patients intolerant of oral bisphosphonates, alternative options include denosumab (a monoclonal antibody against RANKL, given as a subcutaneous injection every 6 months, avoiding oral GI side effects) or an intravenous bisphosphonate such as zoledronic acid (given as an annual infusion, bypassing the GI tract).', 4),
('f5000000-0000-0000-0000-000000000037', 'E', 'Immediate surgical intervention as an alternative to medical therapy', false, 'Ruled out because surgery is not an alternative to medical osteoporosis treatment; medical therapy options (denosumab, IV bisphosphonate, or others) remain the appropriate approach when oral bisphosphonates are not tolerated.', 5),
('f5000000-0000-0000-0000-000000000038', 'A', 'Stopping denosumab without follow-on therapy can cause rebound bone loss and increased vertebral fracture risk', true, $x$Correct. Unlike bisphosphonates (which have a prolonged residual effect on bone even after stopping), denosumab's effect wears off relatively quickly once discontinued, and stopping without appropriate follow-on therapy (typically a bisphosphonate) can cause rapid rebound bone turnover, loss of the gained bone density benefit, and an increased risk of multiple vertebral fractures; doses should not be delayed or stopped without a planned transition.$x$, 1),
('f5000000-0000-0000-0000-000000000038', 'B', 'Denosumab has no specific considerations regarding discontinuation, unlike other osteoporosis treatments', false, 'Ruled out because this significantly understates a genuine, clinically important safety consideration specific to denosumab that differs from other agents like bisphosphonates.', 2),
('f5000000-0000-0000-0000-000000000038', 'C', 'Denosumab should always be continued indefinitely with no possibility of ever stopping or switching treatment', false, 'Ruled out because although stopping without follow-on therapy is risky, treatment can be appropriately transitioned to another agent (typically a bisphosphonate) when discontinuation is being considered, rather than there being no possible pathway to stopping.', 3),
('f5000000-0000-0000-0000-000000000038', 'D', 'This rebound effect only matters for patients under 50 years old', false, 'Ruled out because the rebound bone loss and fracture risk on denosumab discontinuation is relevant across the treated population, not limited to a specific younger age group.', 4),
('f5000000-0000-0000-0000-000000000038', 'E', 'Missing occasional doses has no clinical consequence', false, 'Ruled out because adherence to the strict dosing schedule (typically every 6 months) is specifically important for denosumab, given the risk of rebound effects if doses are significantly delayed.', 5),
('f5000000-0000-0000-0000-000000000039', 'A', 'Bisphosphonates', false, 'Ruled out because bisphosphonates are antiresorptive agents, working by inhibiting osteoclast-mediated bone resorption, not by directly stimulating new bone formation.', 1),
('f5000000-0000-0000-0000-000000000039', 'B', 'Parathyroid hormone analogues (e.g. teriparatide)', true, 'Correct. Teriparatide (a recombinant parathyroid hormone analogue) is an anabolic agent that stimulates new bone formation (rather than simply reducing resorption, as antiresorptive agents like bisphosphonates and denosumab do), making it a useful option for patients with severe osteoporosis or multiple fragility fractures who may benefit from this different mechanism of action.', 2),
('f5000000-0000-0000-0000-000000000039', 'C', 'Denosumab', false, 'Ruled out because denosumab is also an antiresorptive agent (inhibiting osteoclast activity via RANKL inhibition), not a bone-forming (anabolic) agent.', 3),
('f5000000-0000-0000-0000-000000000039', 'D', 'Calcium supplements', false, 'Ruled out because calcium supplementation provides substrate for bone mineralisation but does not itself stimulate new bone formation through a specific anabolic pharmacological mechanism.', 4),
('f5000000-0000-0000-0000-000000000039', 'E', 'Vitamin D supplements', false, 'Ruled out because vitamin D supports calcium absorption and bone mineralisation but does not act as a specific anabolic (bone-forming) agent in the way teriparatide does.', 5),
('f5000000-0000-0000-0000-000000000040', 'A', 'Avoiding all physical activity to protect the joints', false, 'Ruled out because avoiding physical activity would be counterproductive; weight-bearing exercise specifically helps maintain bone density, and inactivity is itself a risk factor for bone loss.', 1),
('f5000000-0000-0000-0000-000000000040', 'B', 'Increasing alcohol intake, as it has no effect on bone health', false, 'Ruled out because excessive alcohol intake is a recognised risk factor for reduced bone density and increased fracture risk, not a neutral or beneficial factor.', 2),
('f5000000-0000-0000-0000-000000000040', 'C', 'Regular weight-bearing exercise, adequate dietary calcium and vitamin D intake, and smoking cessation/limiting alcohol', true, 'Correct. Regular weight-bearing and muscle-strengthening exercise, ensuring adequate dietary calcium and vitamin D (with supplementation if needed), smoking cessation, and limiting excessive alcohol intake are all recommended lifestyle measures that support bone health and help reduce osteoporosis and fragility fracture risk.', 3),
('f5000000-0000-0000-0000-000000000040', 'D', 'Continuing smoking, as it has no relevant effect on bone health', false, 'Ruled out because smoking is a recognised, independent risk factor for reduced bone density and increased fracture risk; smoking cessation is specifically recommended as part of bone health optimisation.', 4),
('f5000000-0000-0000-0000-000000000040', 'E', 'Strict avoidance of all dairy and calcium-containing foods', false, 'Ruled out because adequate calcium intake (often including dietary or supplemental sources) is important for bone health, not something to be strictly avoided.', 5),
('f5000000-0000-0000-0000-000000000041', 'A', 'Urge incontinence', false, 'Ruled out because urge incontinence is characterised by a sudden, strong urge to void immediately preceding leakage (often associated with detrusor overactivity), not the stress-triggered pattern without urge described here.', 1),
('f5000000-0000-0000-0000-000000000041', 'B', 'Overflow incontinence', false, 'Ruled out because overflow incontinence results from bladder outlet obstruction or an underactive detrusor causing chronic retention with overflow leakage, typically presenting with continuous dribbling rather than this specific stress-triggered pattern.', 2),
('f5000000-0000-0000-0000-000000000041', 'C', 'Stress urinary incontinence', true, 'Correct. Involuntary leakage of urine specifically triggered by increased intra-abdominal pressure (coughing, sneezing, laughing, exercise), without a preceding urge, is characteristic of stress incontinence, typically resulting from weakness of the pelvic floor muscles and urethral sphincter mechanism.', 3),
('f5000000-0000-0000-0000-000000000041', 'D', 'Functional incontinence', false, 'Ruled out because functional incontinence reflects an inability to reach the toilet in time due to physical or cognitive limitations, despite normal bladder function, not this specific stress-triggered leakage pattern.', 4),
('f5000000-0000-0000-0000-000000000041', 'E', 'Normal age-related bladder change requiring no assessment', false, 'Ruled out because although some degree of pelvic floor change can occur with age, symptomatic stress incontinence represents a specific, assessable and often treatable condition, not something to simply accept as an inevitable, unaddressed consequence of ageing.', 5),
('f5000000-0000-0000-0000-000000000042', 'A', 'Stress incontinence, managed first-line with pelvic floor exercises', false, 'Ruled out because this presentation (sudden urge preceding leakage) is characteristic of urge, not stress, incontinence (which is specifically triggered by increased abdominal pressure without urge); the appropriate first-line treatment for urge incontinence is bladder training, not pelvic floor exercises alone.', 1),
('f5000000-0000-0000-0000-000000000042', 'B', 'Urge incontinence, managed first-line with bladder training', true, 'Correct. A sudden, compelling urge to void with associated leakage before reaching the toilet, reflecting detrusor overactivity, is characteristic of urge incontinence; bladder training (a structured programme of gradually increasing the interval between voids) is recommended as first-line treatment, with antimuscarinic or other medications considered if this is insufficient.', 2),
('f5000000-0000-0000-0000-000000000042', 'C', 'Overflow incontinence, managed first-line with intermittent catheterisation', false, 'Ruled out because overflow incontinence presents with continuous dribbling from chronic retention, not this urge-predominant pattern; the management approach described does not fit this presentation.', 3),
('f5000000-0000-0000-0000-000000000042', 'D', 'Functional incontinence, managed first-line with environmental modification only', false, 'Ruled out because functional incontinence relates to physical/cognitive barriers to reaching the toilet despite normal bladder function, not the urge-driven pattern with detrusor overactivity described here.', 4),
('f5000000-0000-0000-0000-000000000042', 'E', 'Urinary tract infection requiring antibiotics as the primary treatment', false, 'Ruled out because there is no mention of infective symptoms (dysuria, fever), and this presentation reflects a chronic pattern of urge incontinence rather than an acute infective process.', 5),
('f5000000-0000-0000-0000-000000000043', 'A', 'Stress incontinence', false, 'Ruled out because stress incontinence is triggered specifically by increased abdominal pressure without a raised post-void residual, unlike this pattern of continuous dribbling with significant residual volume.', 1),
('f5000000-0000-0000-0000-000000000043', 'B', 'Urge incontinence', false, 'Ruled out because urge incontinence involves a sudden compelling urge with leakage, not this pattern of continuous dribbling with chronic retention and a significantly raised post-void residual.', 2),
('f5000000-0000-0000-0000-000000000043', 'C', 'Functional incontinence', false, 'Ruled out because functional incontinence relates to physical/cognitive barriers to toileting with normal bladder emptying, not the elevated post-void residual and outlet obstruction described here.', 3),
('f5000000-0000-0000-0000-000000000043', 'D', 'Overflow incontinence secondary to chronic urinary retention', true, 'Correct. Constant dribbling with a sensation of incomplete emptying and a significantly elevated post-void residual volume, in the context of bladder outlet obstruction (benign prostatic hyperplasia), is characteristic of overflow incontinence, where the overdistended bladder leaks small amounts of urine continuously.', 4),
('f5000000-0000-0000-0000-000000000043', 'E', 'Normal bladder function for his age', false, 'Ruled out because a significantly elevated post-void residual and continuous dribbling represent a specific pathological process (overflow incontinence from outlet obstruction) requiring assessment and management, not normal function.', 5),
('f5000000-0000-0000-0000-000000000044', 'A', 'Stress incontinence', false, 'Ruled out because stress incontinence relates to a specific bladder/pelvic floor mechanism (leakage with increased abdominal pressure), which has been excluded here by the normal bladder function assessment; her incontinence relates instead to physical and cognitive barriers to toileting.', 1),
('f5000000-0000-0000-0000-000000000044', 'B', 'Urge incontinence', false, 'Ruled out because urge incontinence involves detrusor overactivity, which has been excluded by normal bladder function assessment; the issue here is functional (mobility/cognitive) rather than bladder-related.', 2),
('f5000000-0000-0000-0000-000000000044', 'C', 'Overflow incontinence', false, 'Ruled out because overflow incontinence involves chronic retention and elevated post-void residual from an underlying bladder/outlet problem, which is not described here, where bladder function itself has been assessed as normal.', 3),
('f5000000-0000-0000-0000-000000000044', 'D', 'A normal, unmodifiable consequence of her dementia requiring no specific intervention', false, 'Ruled out because although her underlying conditions contribute to the functional barriers, specific interventions (toileting programmes, environmental adaptations, addressing mobility) can meaningfully help manage functional incontinence, rather than it being something with no possible modifiable approach.', 4),
('f5000000-0000-0000-0000-000000000044', 'E', 'Functional incontinence', true, 'Correct. Incontinence resulting from physical (mobility) or cognitive barriers to reaching and using the toilet appropriately, despite normal underlying bladder function, defines functional incontinence; management focuses on addressing these barriers (e.g. improving access, prompted/timed toileting, environmental modifications) rather than bladder-specific treatments.', 5),
('f5000000-0000-0000-0000-000000000045', 'A', 'Barthel Index (Activities of Daily Living assessment)', true, 'Correct. The Barthel Index is a widely used, validated tool assessing independence in basic activities of daily living (including bathing, dressing, toileting, transferring, continence and feeding), providing a standardised measure of functional status, useful for tracking change over time and planning ongoing care needs.', 1),
('f5000000-0000-0000-0000-000000000045', 'B', 'Mini-Mental State Examination', false, 'Ruled out because the MMSE assesses cognitive function, not physical functional independence in activities of daily living.', 2),
('f5000000-0000-0000-0000-000000000045', 'C', 'Glasgow Coma Scale', false, 'Ruled out because the Glasgow Coma Scale assesses level of consciousness, not functional independence in daily activities.', 3),
('f5000000-0000-0000-0000-000000000045', 'D', 'Waterlow score', false, 'Ruled out because the Waterlow score assesses pressure ulcer risk, not activities of daily living function.', 4),
('f5000000-0000-0000-0000-000000000045', 'E', 'CHA2DS2-VASc score', false, 'Ruled out because this tool assesses stroke risk in atrial fibrillation, entirely unrelated to functional/activities of daily living assessment.', 5),
('f5000000-0000-0000-0000-000000000046', 'A', 'An inevitable, unmodifiable consequence of the chest infection alone, unrelated to hospitalisation factors', false, 'Ruled out because although the acute illness contributes, hospital-associated factors (prolonged bed rest, reduced mobilisation, environmental factors) significantly contribute to and can be modified to reduce this functional decline, rather than it being solely and unavoidably due to the infection itself.', 1),
('f5000000-0000-0000-0000-000000000046', 'B', 'Normal, expected functional decline unrelated to her hospital stay that would have occurred regardless', false, 'Ruled out because although some functional change can occur with acute illness in any setting, hospital-associated deconditioning specifically relates to factors within the hospital admission that can be actively addressed, rather than being an entirely unrelated, inevitable process.', 2),
('f5000000-0000-0000-0000-000000000046', 'C', 'A new diagnosis of dementia causing this decline', false, 'Ruled out because there is no specific evidence of cognitive impairment described; the functional decline pattern following acute hospitalisation, particularly with bed rest, is more consistent with hospital-associated deconditioning than a new dementia diagnosis.', 3),
('f5000000-0000-0000-0000-000000000046', 'D', 'Malingering to avoid discharge', false, 'Ruled out because this represents a genuine, well-recognised clinical phenomenon (hospital-associated deconditioning) affecting many older hospitalised patients, not deliberate feigning of symptoms.', 4),
('f5000000-0000-0000-0000-000000000046', 'E', 'Hospital-associated deconditioning', true, 'Correct. Older adults, particularly those who are frail, are at significant risk of functional decline during hospital admission, related to factors including prolonged bed rest, reduced mobility, the acute illness itself, and the unfamiliar hospital environment, even after the primary medical problem has resolved; this is a recognised, important phenomenon requiring proactive prevention (early mobilisation, minimising bed rest) and rehabilitation.', 5),
('f5000000-0000-0000-0000-000000000047', 'A', 'No specific preventive measures are needed if the patient is otherwise medically stable', false, 'Ruled out because pressure ulcer risk relates specifically to reduced mobility and other risk factors (nutrition, skin condition, continence), not overall medical stability; proactive preventive measures are needed regardless of general stability if mobility is reduced.', 1),
('f5000000-0000-0000-0000-000000000047', 'B', 'Daily vigorous massage of at-risk skin areas', false, 'Ruled out because vigorous massage of at-risk or reddened skin areas is not recommended and can potentially cause further tissue damage; gentle skin care and repositioning are the appropriate approaches instead.', 2),
('f5000000-0000-0000-0000-000000000047', 'C', 'Restricting fluid intake to reduce skin moisture', false, 'Ruled out because adequate hydration and nutrition actually support skin integrity and wound healing; restricting fluids would not be an appropriate preventive strategy and could be harmful.', 3),
('f5000000-0000-0000-0000-000000000047', 'D', 'Regular repositioning and use of a pressure-relieving mattress, guided by formal pressure ulcer risk assessment', true, 'Correct. Regular repositioning (e.g. every 2-4 hours depending on risk level) combined with appropriate pressure-relieving equipment (mattresses, cushions), guided by formal risk assessment (e.g. using a validated tool such as the Waterlow score) on admission and periodically thereafter, is the cornerstone of pressure ulcer prevention in patients with reduced mobility.', 4),
('f5000000-0000-0000-0000-000000000047', 'E', 'Leaving the patient in a single position to avoid disturbing them', false, 'Ruled out because this is the opposite of appropriate prevention; regular repositioning specifically relieves prolonged pressure on vulnerable areas, reducing pressure ulcer risk.', 5),
('f5000000-0000-0000-0000-000000000048', 'A', 'True infective diarrhoea requiring antibiotic treatment', false, 'Ruled out because the clinical picture described (chronic constipation with a palpable/identified faecal mass and leakage around it) is characteristic of overflow diarrhoea from impaction, not an infective process requiring antibiotics.', 1),
('f5000000-0000-0000-0000-000000000048', 'B', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not typically cause this specific pattern of chronic impaction with overflow leakage; the history here points specifically to faecal impaction as the cause.', 2),
('f5000000-0000-0000-0000-000000000048', 'C', 'Overflow (spurious) diarrhoea secondary to faecal impaction', true, 'Correct. Chronic constipation leading to faecal impaction (a large, hard mass of stool) can cause liquid stool to leak around the obstruction, presenting as apparent diarrhoea or incontinence; management involves disimpaction (often using appropriate laxatives, sometimes combined with enemas) followed by a regular bowel regimen to prevent recurrence.', 3),
('f5000000-0000-0000-0000-000000000048', 'D', 'Inflammatory bowel disease', false, 'Ruled out because there is no description of the typical features of IBD (bloody diarrhoea, weight loss, systemic symptoms); the clinical picture described is specific to chronic constipation with overflow.', 4),
('f5000000-0000-0000-0000-000000000048', 'E', 'Normal bowel pattern for her age requiring no intervention', false, 'Ruled out because faecal impaction with overflow incontinence is a significant, treatable condition causing real symptoms and potential complications, not a normal pattern requiring no action.', 5),
('f5000000-0000-0000-0000-000000000049', 'A', 'The medical team alone, without other professional input', false, 'Ruled out because comprehensive discharge planning for complex, frail older patients benefits from multidisciplinary input addressing functional, social and medication-related factors, not medical assessment alone.', 1),
('f5000000-0000-0000-0000-000000000049', 'B', 'Physiotherapy, occupational therapy, nursing, medical team, social work and pharmacy, working collaboratively', true, 'Correct. Safe, effective discharge planning for a frail older adult following a hospital admission typically involves a multidisciplinary team, including physiotherapy (mobility, strength), occupational therapy (functional assessment, home adaptations), nursing, the medical team (medical optimisation), social work (care package/support arrangement), and pharmacy (medication review), working collaboratively to address the multiple domains relevant to a safe, sustainable discharge.', 2),
('f5000000-0000-0000-0000-000000000049', 'C', 'Physiotherapy alone, focusing only on mobility', false, 'Ruled out because although mobility is important, a comprehensive discharge plan needs to address multiple domains (function, home environment, social support, medications), not mobility in isolation.', 3),
('f5000000-0000-0000-0000-000000000049', 'D', 'No specific planning is needed beyond simply arranging transport home', false, 'Ruled out because this would fail to address the multiple factors relevant to a safe, sustainable discharge for a frail older patient following a fall, risking readmission or further deterioration.', 4),
('f5000000-0000-0000-0000-000000000049', 'E', 'Only family members, without involvement of the clinical multidisciplinary team', false, 'Ruled out because although family involvement is valuable and important, professional multidisciplinary assessment and planning are also essential to properly address medical, functional and care needs.', 5),
('f5000000-0000-0000-0000-000000000050', 'A', 'Consider pharmacological treatment (e.g. an antimuscarinic or beta-3 agonist for the urge component) alongside continued conservative measures', true, 'Correct. When conservative measures (pelvic floor exercises, bladder training) provide only partial benefit for incontinence with a significant urge component, adding pharmacological treatment targeting the urge/overactive bladder component (antimuscarinics or beta-3 agonists such as mirabegron) is an appropriate next step before considering more invasive options such as surgery.', 1),
('f5000000-0000-0000-0000-000000000050', 'B', 'Proceed directly to surgery without trying any further conservative or medical options', false, 'Ruled out because a stepped approach is generally recommended, escalating through conservative and medical management before considering surgical intervention, particularly given her stated preference to explore further options first.', 2),
('f5000000-0000-0000-0000-000000000050', 'C', 'Stop all current treatment, as conservative measures have already been tried and failed completely', false, 'Ruled out because partial improvement suggests conservative measures are providing some benefit and should generally be continued alongside additional treatment, rather than being stopped entirely.', 3),
('f5000000-0000-0000-0000-000000000050', 'D', 'Long-term indwelling urinary catheter as the next appropriate step', false, 'Ruled out because a long-term indwelling catheter carries significant risks (infection, other complications) and is not an appropriate next step when other treatment options (pharmacological therapy) have not yet been tried for her urge component.', 4),
('f5000000-0000-0000-0000-000000000050', 'E', 'Fluid restriction to a minimal intake as the primary next intervention', false, 'Ruled out because significant fluid restriction can cause dehydration and other harms, and is not the recommended primary next step; targeted pharmacological treatment for the urge component is more appropriate.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f5000000-0000-0000-0000-000000000001', 'Recurrent falls (rather than a single, clearly mechanical fall) is a specific indication for comprehensive multifactorial assessment, reflecting the likely presence of multiple contributing factors.', 1),
('f5000000-0000-0000-0000-000000000001', 'This assessment covers a broad range of domains (gait/balance, vision, cardiovascular causes, cognition, medications, environment, bone health) rather than focusing on a single potential cause.', 2),
('f5000000-0000-0000-0000-000000000001', 'Identifying and addressing modifiable risk factors through this structured assessment is the evidence-based approach to reducing future falls risk, rather than premature escalation to care placement or simply providing reassurance.', 3),
('f5000000-0000-0000-0000-000000000002', 'A standardised drop in blood pressure (systolic ≥20 mmHg or diastolic ≥10 mmHg) within 3 minutes of standing, with symptom reproduction, is the diagnostic criterion for postural hypotension.', 1),
('f5000000-0000-0000-0000-000000000002', 'Postural hypotension is a common and important, often medication-related (e.g. antihypertensives, diuretics) and modifiable contributor to falls in older adults.', 2),
('f5000000-0000-0000-0000-000000000002', 'Identifying postural hypotension prompts review of contributing medications, consideration of other causes (e.g. autonomic dysfunction, dehydration), and specific management strategies (e.g. graded mobilisation, compression stockings) as part of falls prevention.', 3),
('f5000000-0000-0000-0000-000000000003', 'The Fried frailty phenotype defines frailty based on meeting three or more of five specific criteria: unintentional weight loss, exhaustion, weakness, slow gait speed, and low physical activity.', 1),
('f5000000-0000-0000-0000-000000000003', 'Frailty is a recognised, distinct clinical syndrome associated with increased vulnerability to stressors and higher risk of adverse outcomes (falls, hospitalisation, disability, mortality), justifying specific clinical attention.', 2),
('f5000000-0000-0000-0000-000000000003', 'Identifying frailty prompts consideration of comprehensive geriatric assessment and targeted interventions (e.g. exercise programmes, nutritional support, medication review) aimed at improving outcomes and quality of life.', 3),
('f5000000-0000-0000-0000-000000000004', 'Festinating gait (progressively shorter, faster steps) and freezing episodes (particularly triggered by turning, narrow spaces, or dual-tasking) are specific, well-recognised features of advanced Parkinsonian gait disturbance.', 1),
('f5000000-0000-0000-0000-000000000004', 'Postural instability, from impaired postural reflexes, is a core Parkinsonian feature that significantly increases falls risk, particularly in more advanced disease.', 2),
('f5000000-0000-0000-0000-000000000004', $x$Recognising these specific gait mechanisms can guide targeted interventions (physiotherapy strategies for freezing, medication optimisation, environmental modifications) as part of falls prevention in Parkinson's disease.$x$, 3),
('f5000000-0000-0000-0000-000000000005', 'The multidimensional nature of CGA (medical, functional, psychological, social) distinguishes it from a standard, single-domain medical assessment.', 1),
('f5000000-0000-0000-0000-000000000005', $x$The multidisciplinary team approach, drawing on various professional perspectives, is central to CGA's effectiveness in addressing the complex, interacting needs of frail older adults.$x$, 2),
('f5000000-0000-0000-0000-000000000005', 'CGA has been shown in evidence to improve outcomes (e.g. likelihood of living at home, reduced mortality) for appropriately selected frail older patients, particularly in the inpatient setting, supporting its use as a structured process rather than ad hoc assessment.', 3),
('f5000000-0000-0000-0000-000000000006', $x$A 'long lie' (typically defined as being unable to get up for an hour or more after a fall) carries specific risks including rhabdomyolysis (from pressure-related muscle damage), hypothermia, dehydration, and pressure sores, beyond the injury from the fall itself.$x$, 1),
('f5000000-0000-0000-0000-000000000006', 'A markedly raised creatine kinase is the key biochemical marker of rhabdomyolysis, and aggressive IV fluid resuscitation is central to preventing or managing the resulting acute kidney injury.', 2),
('f5000000-0000-0000-0000-000000000006', 'Recognising and asking about the duration of a long lie is an important part of assessing fall-related risk, as it significantly changes the necessary immediate management priorities beyond simply addressing any traumatic injury.', 3),
('f5000000-0000-0000-0000-000000000007', 'The Timed Up and Go test is a simple, quick, validated tool assessing multiple components of functional mobility relevant to falls risk (sit-to-stand transfer, gait, turning, balance) in a single practical assessment.', 1),
('f5000000-0000-0000-0000-000000000007', 'A prolonged completion time is associated with increased falls risk, making this a useful, easily administered screening tool as part of a broader falls risk assessment.', 2),
('f5000000-0000-0000-0000-000000000007', 'It complements, rather than replaces, other components of comprehensive falls assessment (e.g. postural blood pressure, vision testing, medication review, cognitive screening).', 3),
('f5000000-0000-0000-0000-000000000008', 'Fracture risk is the product of both the likelihood of a fall (mechanical trigger) and the underlying bone strength (determining whether that fall results in a fracture), justifying a combined management approach.', 1),
('f5000000-0000-0000-0000-000000000008', 'Falls prevention strategies (addressing gait/balance, vision, medications, environment) and bone-protective treatment (e.g. bisphosphonates, calcium/vitamin D) work through complementary mechanisms to reduce overall fragility fracture risk.', 2),
('f5000000-0000-0000-0000-000000000008', 'This integrated approach reflects the general principle in geriatric medicine of addressing multiple interacting risk factors together, rather than managing individual conditions in isolation.', 3),
('f5000000-0000-0000-0000-000000000009', 'Individualised assessment of likely prognosis and the balance of benefits versus burdens of different treatment intensities is central to appropriate decision-making, rather than applying blanket rules based on age or frailty alone.', 1),
('f5000000-0000-0000-0000-000000000009', $x$Shared decision-making, incorporating the patient's own wishes (directly or through advance care planning/family understanding) is a fundamental ethical and legal principle in these discussions.$x$, 2),
('f5000000-0000-0000-0000-000000000009', 'Proactive, timely discussions about goals of care, ideally before acute crisis, allow for more considered, patient-centred decision-making than decisions made reactively during acute deterioration.', 3),
('f5000000-0000-0000-0000-000000000010', 'The electronic frailty index leverages existing routinely collected primary care data, allowing efficient, systematic frailty screening across a whole practice population without requiring additional appointments purely for screening purposes.', 1),
('f5000000-0000-0000-0000-000000000010', 'Categorising patients by frailty severity (fit, mild, moderate, severe) helps target more detailed assessment and intervention (e.g. medication review, comprehensive geriatric assessment) towards those most likely to benefit.', 2),
('f5000000-0000-0000-0000-000000000010', 'Population-level frailty screening tools like the eFI complement, rather than replace, more detailed individual assessment tools (e.g. Timed Up and Go, Fried criteria) used once frailty has been identified.', 3),
('f5000000-0000-0000-0000-000000000011', 'Acute onset (hours to days) with fluctuating course is the key feature distinguishing delirium from the gradual, progressive decline of dementia.', 1),
('f5000000-0000-0000-0000-000000000011', 'Inattention (difficulty focusing, sustaining or shifting attention) is a core diagnostic feature of delirium.', 2),
('f5000000-0000-0000-0000-000000000011', 'Identifying and treating the underlying precipitant (here, infection) is central to delirium management, alongside supportive, non-pharmacological measures to reduce distress and risk.', 3),
('f5000000-0000-0000-0000-000000000012', $x$The CAM's structure (acute onset/fluctuation AND inattention, plus either disorganised thinking OR altered consciousness) provides a specific, validated framework for delirium diagnosis, distinguishing it from general cognitive screening tools.$x$, 1),
('f5000000-0000-0000-0000-000000000012', 'General cognitive screening tools (MMSE, AMTS) assess overall cognitive performance but are not specifically designed to diagnose delirium as a distinct acute syndrome.', 2),
('f5000000-0000-0000-0000-000000000012', 'Using a structured, validated tool like the CAM improves consistency and accuracy in delirium recognition, which is important given how frequently delirium is under-recognised in clinical practice.', 3),
('f5000000-0000-0000-0000-000000000013', 'Non-pharmacological measures (reorientation, addressing sensory impairment, minimising environmental disruption, involving familiar people) remain the foundation of delirium management and should be optimised before considering medication.', 1),
('f5000000-0000-0000-0000-000000000013', 'When pharmacological treatment is needed for significant agitation posing risk, low-dose antipsychotics are generally preferred over benzodiazepines (which can worsen delirium in most contexts, aside from specific situations like alcohol withdrawal).', 2),
('f5000000-0000-0000-0000-000000000013', 'Any pharmacological treatment should be at the lowest effective dose, for the shortest necessary duration, with regular review, alongside continued identification and treatment of the underlying precipitating cause(s) of the delirium.', 3),
('f5000000-0000-0000-0000-000000000014', 'A gradual, progressive (rather than acute or fluctuating) onset over months to years is characteristic of dementia in general, distinguishing it from delirium.', 1),
('f5000000-0000-0000-0000-000000000014', $x$Early, prominent impairment of short-term memory, alongside language and visuospatial difficulties, is a classic pattern for Alzheimer's disease specifically, distinguishing it from the stepwise course of vascular dementia or the early behavioural/language predominance of frontotemporal dementia.$x$, 2),
('f5000000-0000-0000-0000-000000000014', $x$Alzheimer's disease is the most common cause of dementia overall, making it the most likely diagnosis when this classic gradual, amnestic-predominant pattern is present, though other causes should still be considered and excluded as appropriate.$x$, 3),
('f5000000-0000-0000-0000-000000000015', 'A stepwise, rather than smoothly progressive, decline pattern, with discrete episodes of worsening corresponding to identified vascular events, is the classic hallmark of vascular dementia.', 1),
('f5000000-0000-0000-0000-000000000015', 'Focal neurological signs on examination, reflecting the underlying cerebrovascular pathology, support this diagnosis and distinguish it from the primarily cognitive/behavioural presentations of neurodegenerative dementias without focal signs.', 2),
('f5000000-0000-0000-0000-000000000015', 'Managing vascular risk factors (blood pressure, cholesterol, diabetes, smoking, antiplatelet therapy where appropriate) is an important part of vascular dementia management, aiming to reduce further cerebrovascular events and disease progression.', 3),
('f5000000-0000-0000-0000-000000000016', 'Recurrent, detailed visual hallucinations occurring relatively early in the disease course are a core, distinguishing feature of dementia with Lewy bodies.', 1),
('f5000000-0000-0000-0000-000000000016', $x$REM sleep behaviour disorder (acting out dreams during REM sleep) is a recognised, often early feature strongly associated with Lewy body pathology (dementia with Lewy bodies and Parkinson's disease).$x$, 2),
('f5000000-0000-0000-0000-000000000016', $x$The timing relationship between motor parkinsonism and cognitive decline (parkinsonism preceding dementia by more than a year favours Parkinson's disease dementia; concurrent or dementia-first onset favours dementia with Lewy bodies) is a key diagnostic distinguishing feature between these two related Lewy body disorders.$x$, 3),
('f5000000-0000-0000-0000-000000000017', $x$Neuroleptic sensitivity reactions in dementia with Lewy bodies can be severe and life-threatening, including marked worsening of parkinsonism, severe sedation, autonomic dysfunction and increased mortality, distinguishing this population's antipsychotic risk profile from other dementias.$x$, 1),
('f5000000-0000-0000-0000-000000000017', $x$This specific sensitivity is thought to relate to the underlying Lewy body pathology's effect on dopaminergic pathways, making this population particularly vulnerable to dopamine-blocking effects.$x$, 2),
('f5000000-0000-0000-0000-000000000017', 'When antipsychotic treatment is felt to be unavoidable for severe symptoms, specialist involvement, use of an atypical agent, and extremely cautious, low-dose, closely monitored prescribing are essential, reflecting the balance between symptom control and this significant safety risk.', 3),
('f5000000-0000-0000-0000-000000000018', 'Early, predominant behavioural and personality change (rather than memory impairment) as the initial and leading feature is the hallmark of the behavioural variant of frontotemporal dementia.', 1),
('f5000000-0000-0000-0000-000000000018', $x$Relative preservation of memory and visuospatial function in the earlier stages helps distinguish frontotemporal dementia from the typically amnestic-predominant early presentation of Alzheimer's disease.$x$, 2),
('f5000000-0000-0000-0000-000000000018', $x$Frontotemporal dementia often presents at a younger age (commonly 45-65) compared with the more typical later-onset pattern of Alzheimer's disease, though there is overlap.$x$, 3),
('f5000000-0000-0000-0000-000000000019', $x$The classic triad (gait disturbance, urinary incontinence, cognitive decline) -- sometimes remembered as 'wet, wobbly and wacky' -- is characteristic of normal pressure hydrocephalus, though gait disturbance is often the earliest and most prominent feature.$x$, 1),
('f5000000-0000-0000-0000-000000000019', 'Ventricular enlargement disproportionate to the degree of cortical atrophy on imaging is a key radiological feature distinguishing NPH from other causes of dementia with generalised atrophy.', 2),
('f5000000-0000-0000-0000-000000000019', 'NPH is important to recognise as one of the few potentially reversible causes of dementia-like symptoms, with some patients showing significant improvement following CSF shunting, particularly if gait disturbance is the predominant and earliest symptom.', 3),
('f5000000-0000-0000-0000-000000000020', 'Multicomponent non-pharmacological interventions addressing multiple modifiable risk factors together (hydration, pain, sensory impairment, sleep, orientation, mobility) have the best evidence for reducing delirium incidence.', 1),
('f5000000-0000-0000-0000-000000000020', 'Hip fracture patients are at particularly high risk of delirium, making proactive preventive strategies especially important in this population.', 2),
('f5000000-0000-0000-0000-000000000020', 'These preventive strategies overlap substantially with the non-pharmacological management approaches used once delirium has developed, reflecting a continuum of care addressing the same underlying modifiable factors.', 3),
('f5000000-0000-0000-0000-000000000021', 'A structured medication review considers each medication individually against clear criteria (indication, benefit, harm, appropriateness), rather than applying blanket rules.', 1),
('f5000000-0000-0000-0000-000000000021', $x$Considering the patient's overall goals of care and prognosis is essential, as the risk-benefit balance of preventive medications can shift significantly in the context of significant frailty or limited life expectancy.$x$, 2),
('f5000000-0000-0000-0000-000000000021', 'This structured approach forms the basis for potential deprescribing decisions, which should be made collaboratively with the patient, considering both the evidence and their own priorities and preferences.', 3),
('f5000000-0000-0000-0000-000000000022', 'Many commonly prescribed medications (tricyclic antidepressants, some antihistamines, some bladder antimuscarinics) have anticholinergic properties, and their effects are cumulative when multiple such drugs are combined.', 1),
('f5000000-0000-0000-0000-000000000022', 'Older adults are particularly susceptible to anticholinergic adverse effects, including confusion, due to age-related changes in drug metabolism and increased blood-brain barrier permeability.', 2),
('f5000000-0000-0000-0000-000000000022', 'Anticholinergic burden scoring tools can help identify and quantify this cumulative risk, guiding medication review and potential deprescribing or switching to lower-anticholinergic-burden alternatives where appropriate.', 3),
('f5000000-0000-0000-0000-000000000023', 'STOPP/START criteria are specifically designed and validated for identifying potentially inappropriate prescribing (both medications that should potentially be stopped and beneficial medications that may be missing) in older adults.', 1),
('f5000000-0000-0000-0000-000000000023', 'Using such structured, validated tools improves the consistency and thoroughness of medication reviews compared with unstructured clinical judgement alone.', 2),
('f5000000-0000-0000-0000-000000000023', $x$These tools complement, rather than replace, individualised clinical assessment considering the specific patient's overall context, preferences and goals of care.$x$, 3),
('f5000000-0000-0000-0000-000000000024', $x$The 'time to benefit' concept -- considering how long a preventive medication typically takes to show meaningful benefit -- is central to appropriate deprescribing decisions in patients with limited life expectancy.$x$, 1),
('f5000000-0000-0000-0000-000000000024', 'Medications providing symptomatic benefit (e.g. analgesics) are generally distinguished from those providing only long-term preventive benefit (e.g. statins, bisphosphonates) when considering deprescribing priorities in this context.', 2),
('f5000000-0000-0000-0000-000000000024', 'This approach reflects a shift towards person-centred, goals-of-care-aligned prescribing in patients with significant frailty or limited prognosis, rather than continuing to apply standard long-term prevention guidelines developed for a general, healthier population.', 3),
('f5000000-0000-0000-0000-000000000025', 'Individualised blood pressure targets, taking into account frailty, falls risk and overall clinical context, are increasingly recognised as appropriate in older adults, rather than rigidly applying standard target thresholds developed from broader population trials.', 1),
('f5000000-0000-0000-0000-000000000025', 'Postural hypotension is a recognised, often medication-related and modifiable contributor to falls risk, making medication review a key part of falls prevention in affected patients.', 2),
('f5000000-0000-0000-0000-000000000025', 'Balancing the competing risks of under-treated hypertension against over-treatment causing postural hypotension and falls requires individualised clinical judgement rather than a one-size-fits-all approach.', 3),
('f5000000-0000-0000-0000-000000000026', 'Individualised glycaemic targets in older adults, particularly with cognitive impairment or frailty, generally aim for less stringent control than in younger, fitter patients, reflecting the different balance of risks and benefits.', 1),
('f5000000-0000-0000-0000-000000000026', 'Hypoglycaemia carries significant risks in older adults, including falls, confusion, and cardiovascular events, making its avoidance a priority that can outweigh the modest microvascular benefits of very tight glycaemic control, particularly given the longer time-to-benefit of intensive control for these complications.', 2),
('f5000000-0000-0000-0000-000000000026', 'This reflects a broader principle in geriatric medicine of adjusting standard treatment targets developed in younger populations to better suit the risk-benefit balance in older, frailer patients.', 3),
('f5000000-0000-0000-0000-000000000027', 'Medication reconciliation -- ensuring an accurate, complete and accessible medication list at every point of care and prescribing decision -- is essential to prevent missed interactions, particularly during transitions of care or when different services are involved.', 1),
('f5000000-0000-0000-0000-000000000027', $x$Trimethoprim's inhibition of warfarin metabolism is a well-recognised, clinically significant interaction that requires either choosing an alternative antibiotic or, if trimethoprim is felt necessary, close INR monitoring.$x$, 2),
('f5000000-0000-0000-0000-000000000027', 'This scenario illustrates a broader patient safety principle: polypharmacy increases the complexity and risk of care, making robust systems for medication reconciliation particularly important for patients on multiple medications, especially those with a narrow therapeutic index like warfarin.', 3),
('f5000000-0000-0000-0000-000000000028', 'A prescribing cascade specifically involves misattributing a drug side effect to a new medical condition, leading to a new drug being prescribed to treat what is actually an adverse effect of an existing medication.', 1),
('f5000000-0000-0000-0000-000000000028', 'Fragmented care across multiple prescribers, without a single coordinated overview of the complete medication list, increases the risk of both prescribing cascades and other polypharmacy-related harms.', 2),
('f5000000-0000-0000-0000-000000000028', 'Regular, structured medication review (ideally involving a single coordinating clinician or pharmacist with full visibility of the complete regimen) is important to identify and address these accumulated, sometimes outdated or inappropriate, prescriptions.', 3),
('f5000000-0000-0000-0000-000000000029', 'Dosette boxes are a practical, widely used tool to support adherence, particularly useful for patients with mild cognitive impairment or complex regimens, without requiring more intensive intervention.', 1),
('f5000000-0000-0000-0000-000000000029', 'Alongside such practical aids, simplifying the medication regimen itself (reducing dosing frequency, minimising unnecessary medications) through structured review can further support adherence.', 2),
('f5000000-0000-0000-0000-000000000029', 'Choosing the appropriate level of adherence support should match the specific difficulty identified, avoiding both under-support (relying on memory alone) and disproportionate over-intervention (e.g. daily hospital attendance) for a problem that simpler measures can address.', 3),
('f5000000-0000-0000-0000-000000000030', $x$Each of the three drug classes independently affects renal haemodynamics; in combination, their effects compound to significantly impair the kidney's ability to autoregulate glomerular filtration, particularly during any additional physiological stress (e.g. dehydration, intercurrent illness).$x$, 1),
('f5000000-0000-0000-0000-000000000030', $x$This 'triple whammy' combination is a well-recognised, specific medication safety concern, particularly relevant in older adults who often have several of these drug classes prescribed for different comorbidities.$x$, 2),
('f5000000-0000-0000-0000-000000000030', $x$Recognising this risk should prompt caution when this combination is used, particularly during acute illness, with consideration of temporarily withholding one or more of the agents ('sick day rules') during periods of risk such as dehydration or intercurrent infection.$x$, 3),
('f5000000-0000-0000-0000-000000000031', 'A fracture occurring from a fall from standing height or less (low-energy trauma) is classified as a fragility fracture, strongly suggesting underlying osteoporosis or reduced bone strength.', 1),
('f5000000-0000-0000-0000-000000000031', 'DEXA scanning and/or fracture risk assessment tools (e.g. FRAX or QFracture) help quantify future fracture risk and guide decisions about starting bone-protective treatment.', 2),
('f5000000-0000-0000-0000-000000000031', 'A prior fragility fracture is itself one of the strongest predictors of future fracture risk, making appropriate assessment and treatment following such an event particularly important for secondary prevention.', 3),
('f5000000-0000-0000-0000-000000000032', 'Oral bisphosphonates are first-line for most patients with osteoporosis, given their established efficacy, relatively favourable safety profile, and cost-effectiveness compared with other agents.', 1),
('f5000000-0000-0000-0000-000000000032', 'Bisphosphonates work by inhibiting osteoclast activity, reducing bone resorption and helping to preserve or modestly increase bone density over time.', 2),
('f5000000-0000-0000-0000-000000000032', 'Adequate calcium and vitamin D status should be ensured alongside bisphosphonate therapy, as they are required for the bisphosphonate to be maximally effective, though they are not sufficient treatment alone.', 3),
('f5000000-0000-0000-0000-000000000033', 'Oral bisphosphonates have poor and variable bioavailability, which is further reduced by food, other medications (particularly calcium and iron), or beverages other than plain water, making empty-stomach administration essential.', 1),
('f5000000-0000-0000-0000-000000000033', 'Remaining upright after the dose reduces the risk of the tablet causing oesophageal irritation or oesophagitis, a recognised adverse effect of this drug class.', 2),
('f5000000-0000-0000-0000-000000000033', 'Correct administration technique is essential patient counselling, as incorrect administration can both reduce efficacy and increase the risk of adverse effects.', 3),
('f5000000-0000-0000-0000-000000000034', 'Atypical femoral fractures are a rare but important complication of prolonged (typically over 5 years) bisphosphonate use, thought to relate to excessive suppression of normal bone remodelling and turnover.', 1),
('f5000000-0000-0000-0000-000000000034', 'Prodromal thigh or groin pain, sometimes present for weeks before the fracture, and characteristic radiographic features (transverse fracture line, cortical thickening/beaking) help distinguish this from typical osteoporotic fractures.', 2),
('f5000000-0000-0000-0000-000000000034', $x$Recognition of this complication has led to recommendations for periodic treatment review (e.g. 'drug holidays' after several years of bisphosphonate use) to balance ongoing fracture prevention benefit against this rare but significant risk.$x$, 3),
('f5000000-0000-0000-0000-000000000035', 'Osteonecrosis of the jaw is a rare complication where bisphosphonates (and other antiresorptive agents) impair normal bone healing and turnover in the jaw, particularly following invasive dental procedures that disrupt bone.', 1),
('f5000000-0000-0000-0000-000000000035', 'The risk is significantly higher with high-dose IV bisphosphonate therapy (as used in cancer treatment) compared with the lower oral doses used for osteoporosis, though the risk is not zero in the osteoporosis population.', 2),
('f5000000-0000-0000-0000-000000000035', 'Good dental health maintenance and appropriate precautions/timing around invasive dental procedures are recommended for patients on long-term bisphosphonate therapy to help minimise this risk.', 3),
('f5000000-0000-0000-0000-000000000036', 'Glucocorticoid-induced osteoporosis is a well-recognised, significant and dose/duration-dependent risk, with guidance specifically addressing when to consider bone protection based on steroid dose and treatment duration.', 1),
('f5000000-0000-0000-0000-000000000036', 'Bone loss with glucocorticoids occurs relatively rapidly, particularly in the first few months of treatment, which is why proactive risk assessment (rather than waiting for a fracture) is recommended for patients on significant, ongoing steroid therapy.', 2),
('f5000000-0000-0000-0000-000000000036', 'Bisphosphonates remain a common first-line choice for glucocorticoid-induced osteoporosis prevention/treatment, similar to postmenopausal osteoporosis, though the specific risk assessment approach and thresholds for treatment differ somewhat from general postmenopausal osteoporosis guidance.', 3),
('f5000000-0000-0000-0000-000000000037', 'Denosumab avoids the oral administration route entirely, making it a useful option for patients with GI intolerance to oral bisphosphonates, though it requires strict adherence to the dosing schedule given rebound bone loss/fracture risk if doses are significantly delayed or stopped without follow-on treatment.', 1),
('f5000000-0000-0000-0000-000000000037', 'IV bisphosphonates (e.g. zoledronic acid) also bypass the GI tract, avoiding oral tolerability issues, while still providing effective antiresorptive treatment via the same general mechanism as oral agents.', 2),
('f5000000-0000-0000-0000-000000000037', 'Choice between these alternatives depends on individual patient factors (renal function, ability to attend for infusions/injections, other comorbidities), reflecting a personalised approach to second-line osteoporosis treatment selection.', 3),
('f5000000-0000-0000-0000-000000000038', $x$Denosumab's reversible mechanism of action (rather than the prolonged skeletal retention seen with bisphosphonates) means its antiresorptive effect diminishes relatively quickly after the next scheduled dose is missed or treatment is stopped.$x$, 1),
('f5000000-0000-0000-0000-000000000038', 'This rebound phenomenon, with rapid loss of accrued bone density and increased risk of multiple vertebral fractures, is a specific, well-documented safety consideration distinguishing denosumab from bisphosphonate therapy.', 2),
('f5000000-0000-0000-0000-000000000038', 'When denosumab needs to be stopped, transitioning to a follow-on bisphosphonate is generally recommended to help preserve the bone density gains and reduce rebound fracture risk.', 3),
('f5000000-0000-0000-0000-000000000039', 'Teriparatide represents a distinct anabolic mechanism (stimulating osteoblast activity and new bone formation) compared with the antiresorptive mechanism (reducing osteoclast-mediated bone breakdown) of bisphosphonates and denosumab.', 1),
('f5000000-0000-0000-0000-000000000039', 'Anabolic therapy is typically reserved for patients with severe osteoporosis or multiple fragility fractures, given its cost and the practical considerations of daily injection and a typically time-limited treatment course.', 2),
('f5000000-0000-0000-0000-000000000039', 'Following a course of anabolic therapy, transitioning to an antiresorptive agent is generally recommended to help maintain the bone density gains achieved, reflecting a sequential treatment approach in severe osteoporosis management.', 3),
('f5000000-0000-0000-0000-000000000040', 'Weight-bearing exercise provides mechanical loading that stimulates bone formation and helps maintain bone density, making it a key modifiable lifestyle factor.', 1),
('f5000000-0000-0000-0000-000000000040', 'Both smoking and excessive alcohol intake are independent, modifiable risk factors for reduced bone density and increased fracture risk, making cessation/moderation important preventive advice.', 2),
('f5000000-0000-0000-0000-000000000040', 'These lifestyle measures complement, rather than replace, pharmacological treatment when osteoporosis is already established and significant fracture risk is present.', 3),
('f5000000-0000-0000-0000-000000000041', 'The specific trigger pattern -- leakage with increased abdominal pressure (coughing, sneezing) without preceding urge -- is the defining clinical feature of stress incontinence.', 1),
('f5000000-0000-0000-0000-000000000041', 'Pelvic floor muscle weakness, often related to childbirth, menopause or ageing, is the underlying mechanism, distinguishing it from the detrusor overactivity mechanism of urge incontinence.', 2),
('f5000000-0000-0000-0000-000000000041', 'Pelvic floor muscle training (physiotherapy) is a first-line, evidence-based treatment for stress incontinence, reflecting the underlying muscular mechanism.', 3),
('f5000000-0000-0000-0000-000000000042', 'A sudden, compelling urge preceding leakage is the defining feature of urge incontinence, reflecting involuntary detrusor muscle contractions (detrusor overactivity).', 1),
('f5000000-0000-0000-0000-000000000042', 'Bladder training, aiming to gradually increase the interval between voids and improve bladder capacity/control, is the recommended first-line, non-pharmacological treatment for urge incontinence.', 2),
('f5000000-0000-0000-0000-000000000042', 'If bladder training alone is insufficient, pharmacological options (antimuscarinics, or beta-3 agonists such as mirabegron, particularly favoured in older adults given lower anticholinergic burden concerns) can be considered as an adjunct.', 3),
('f5000000-0000-0000-0000-000000000043', 'A significantly elevated post-void residual volume, measured by bladder scan, is the key objective finding confirming overflow incontinence from incomplete bladder emptying, distinguishing it from other incontinence types.', 1),
('f5000000-0000-0000-0000-000000000043', 'Bladder outlet obstruction (commonly from benign prostatic hyperplasia in men) is a classic underlying cause, though overflow incontinence can also result from an underactive detrusor muscle.', 2),
('f5000000-0000-0000-0000-000000000043', 'Management addresses the underlying cause (e.g. treating BPH) and may require catheterisation (intermittent or indwelling) to manage retention while definitive treatment is arranged.', 3),
('f5000000-0000-0000-0000-000000000044', 'Functional incontinence is specifically defined by normal underlying bladder function combined with physical or cognitive barriers preventing timely, appropriate toileting.', 1),
('f5000000-0000-0000-0000-000000000044', 'This distinguishes it from the other incontinence types (stress, urge, overflow), which involve a specific bladder/pelvic floor pathophysiological mechanism.', 2),
('f5000000-0000-0000-0000-000000000044', 'Management for functional incontinence focuses on addressing the underlying barriers -- improving mobility/access to toilet facilities, prompted or timed toileting schedules, and appropriate use of continence aids -- rather than bladder-specific pharmacological treatment.', 3),
('f5000000-0000-0000-0000-000000000045', 'The Barthel Index specifically measures basic activities of daily living, providing a standardised score useful for assessing baseline function, tracking recovery, and informing discharge planning and care needs.', 1),
('f5000000-0000-0000-0000-000000000045', 'This differs from instrumental activities of daily living (IADL) scales, which assess more complex tasks (e.g. managing finances, medication, using transport), often used to assess higher-level independence.', 2),
('f5000000-0000-0000-0000-000000000045', 'Using validated functional assessment tools supports objective tracking of functional decline or recovery over time, informing rehabilitation and care planning decisions.', 3),
('f5000000-0000-0000-0000-000000000046', 'Even relatively short hospital admissions can result in significant functional decline in older, frail patients, particularly related to reduced mobility and prolonged bed rest during the admission.', 1),
('f5000000-0000-0000-0000-000000000046', 'This decline can persist even after the acute medical problem (here, the chest infection) has resolved, highlighting that functional recovery may lag behind medical recovery.', 2),
('f5000000-0000-0000-0000-000000000046', 'Proactive strategies -- early mobilisation, minimising unnecessary bed rest, maintaining normal activities where possible during admission -- are important preventive measures, alongside appropriate rehabilitation input to support functional recovery.', 3),
('f5000000-0000-0000-0000-000000000047', 'Regular repositioning directly addresses the core mechanism of pressure ulcer development (prolonged, unrelieved pressure on vulnerable areas, particularly over bony prominences).', 1),
('f5000000-0000-0000-0000-000000000047', 'Formal risk assessment tools help identify patients at higher risk, guiding the intensity of preventive measures (repositioning frequency, equipment) needed for each individual.', 2),
('f5000000-0000-0000-0000-000000000047', 'Additional factors (nutrition, skin hygiene, continence management) also contribute to overall pressure ulcer risk and prevention, reflecting a multifactorial approach similar to other geriatric syndromes.', 3),
('f5000000-0000-0000-0000-000000000048', 'A key clinical clue is the paradoxical presentation of apparent diarrhoea or incontinence occurring in the context of underlying chronic constipation, which can be easily misdiagnosed as true diarrhoea if the underlying impaction is not identified (e.g. via abdominal or rectal examination).', 1),
('f5000000-0000-0000-0000-000000000048', 'Management requires addressing the underlying impaction (disimpaction) rather than treating the leakage as if it were true diarrhoea, which would not resolve the underlying problem and could worsen it if anti-diarrhoeal agents were used.', 2),
('f5000000-0000-0000-0000-000000000048', 'A regular bowel management regimen (adequate fluid, fibre, and often regular laxative use) following disimpaction is important to prevent recurrence of this pattern.', 3),
('f5000000-0000-0000-0000-000000000049', 'A multidisciplinary approach reflects the multiple interacting domains (medical, functional, social, medication-related) relevant to safe discharge planning for frail older adults, mirroring the holistic principle of comprehensive geriatric assessment.', 1),
('f5000000-0000-0000-0000-000000000049', 'Each team member contributes a specific, complementary perspective: physiotherapy and occupational therapy address functional capability and home environment, social work addresses care package needs, and pharmacy addresses medication safety.', 2),
('f5000000-0000-0000-0000-000000000049', 'Effective multidisciplinary discharge planning has been shown to reduce readmission risk and support safer, more sustainable return to independent living for appropriately assessed patients.', 3),
('f5000000-0000-0000-0000-000000000050', 'A stepped, escalating approach to incontinence management -- conservative measures, then pharmacological treatment, then more invasive options if needed -- is the standard evidence-based approach.', 1),
('f5000000-0000-0000-0000-000000000050', 'For mixed incontinence, treatment often needs to address both the stress and urge components, which may include continuing pelvic floor exercises while adding pharmacological treatment for the overactive bladder/urge element.', 2),
('f5000000-0000-0000-0000-000000000050', 'Patient preference and the degree of bother from symptoms appropriately guide how quickly to escalate through this stepped approach, balancing effectiveness against the invasiveness and side-effect profile of each treatment level.', 3);
